// Erzeugt von scripts/build-data.mjs – nicht von Hand bearbeiten (Quelle: data/src).
window.MEDI_DETAILS = Object.assign(window.MEDI_DETAILS || {}, {"tacrolimus":{"wirkmechanismus":"Bremst die Immunabwehr, damit ein transplantiertes Organ nicht abgestossen wird bzw. die Hautentzündung abklingt. Tacrolimus bindet in T-Lymphozyten an das Protein FKBP12; dieser Komplex hemmt das Enzym Calcineurin. Dadurch wird die Bildung von Interleukin-2 und weiteren Botenstoffen blockiert und die Aktivierung der T-Zellen verhindert. Abgebaut wird es über CYP3A4; die Blutspiegel schwanken stark und müssen überwacht werden.","nebenwirkungen":{"sehrHaeufig":["Zittern (Tremor), Kopfschmerzen, Schlafstörungen","Hyperglykämie, Diabetes mellitus, Hyperkaliämie","Bluthochdruck","Nierenfunktionsstörung","Durchfall, Übelkeit","Infektionen","Salbe: Brennen, Juckreiz, Rötung an der Auftragsstelle"],"haeufig":["Blutarmut, Leukopenie, Thrombozytopenie","Magnesium-, Kalium- oder Calciummangel, erhöhte Blutfette","Krampfanfälle, Kribbeln, Bewusstseinsstörungen","Sehstörungen, Ohrensausen","Herzrasen, Durchblutungsstörungen des Herzens","Erhöhte Leberwerte, Gallenstau","Haarausfall, Juckreiz, Ausschlag","Salbe: Hautinfektionen (Herpes, Follikulitis), Gesichtsrötung nach Alkohol"],"gelegentlich":["Herzinsuffizienz, Kammerrhythmusstörungen","Enzephalopathie, Lähmungen","Pankreatitis (Bauchspeicheldrüsenentzündung)","Nierenversagen"],"selten":["Thrombotisch-thrombozytopenische Purpura","Hypertrophe Kardiomyopathie","Toxische epidermale Nekrolyse"],"sehrSelten":["Hörverlust"],"unbekannt":["QT-Verlängerung, Torsade de pointes","Posteriores reversibles Enzephalopathie-Syndrom (PRES)","Agranulozytose, Aplasie der roten Blutzellen","Lymphome und andere Krebserkrankungen, Hautkrebs","Sehnervschädigung (Optikusneuropathie)"]},"schwangerschaft":"Kapseln: nur wenn unbedingt nötig und unter enger Überwachung von Mutter und Kind (Frühgeburt, erhöhtes Kalium und Nierenfunktionsstörung beim Neugeborenen möglich). Salbe: nur wenn eindeutig erforderlich.","stillzeit":"Tacrolimus geht in die Muttermilch über; gemäss Fachinformation während der Behandlung nicht stillen.","hinweise":["Präparate (Prograf, Advagraf, Envarsus) sind nicht direkt austauschbar – nur auf ärztliche Anordnung wechseln; regelmässig Blutspiegel, Nierenwerte, Kalium und Blutzucker kontrollieren.","Kapseln auf nüchternen Magen (1 Stunde vor oder 2–3 Stunden nach dem Essen) einnehmen; keine Grapefruit.","Sonne und Solarium meiden, guter Sonnenschutz; regelmässige Hautkontrollen.","Salbe: nach Alkohol kann das Gesicht stark rot werden; Haut nicht luftdicht abdecken."],"darreichung":["Kapseln","Retardkapseln","Retardtabletten","Granulat zur Herstellung einer Suspension","Infusionskonzentrat","Salbe"]},"tadalafil":{"wirkmechanismus":"Verbessert bei sexueller Erregung den Bluteinstrom in den Penis, entspannt die Muskulatur von Prostata und Blasenhals und erweitert die Lungengefässe. Tadalafil hemmt selektiv die Phosphodiesterase 5, die den Botenstoff cGMP abbaut; dadurch verstärkt sich die gefässerweiternde Wirkung von Stickstoffmonoxid in Schwellkörpern, Prostata, Blase und Lungenarterien. Wegen der langen Halbwertszeit von etwa 17,5 Stunden hält die Wirkung bis zu 36 Stunden an.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen und Gesichtsrötung (bei Lungenhochdruck-Dosierung sehr häufig, sonst häufig)"],"haeufig":["Verdauungsbeschwerden (Dyspepsie), Reflux","Rückenschmerzen, Muskelschmerzen, Gliederschmerzen","Verstopfte Nase","Schwindel","Übelkeit (bei Lungenhochdruck-Dosierung)"],"gelegentlich":["Überempfindlichkeitsreaktionen, Hautausschlag","Verschwommenes Sehen, Augenschmerzen","Ohrensausen (Tinnitus)","Herzrasen, Herzklopfen","Blutdruckabfall oder Blutdruckanstieg","Atemnot, Nasenbluten","Bauchschmerzen, Erbrechen","Blut im Urin, verlängerte Erektionen","Brustschmerzen, Wassereinlagerungen, Müdigkeit"],"selten":["Angioödem, Gesichtsschwellung, Nesselsucht","Schlaganfall, TIA, Ohnmacht, Krampfanfälle, vorübergehender Gedächtnisverlust","Herzinfarkt, plötzlicher Herztod","NAION (Durchblutungsstörung des Sehnervs), Netzhautgefässverschluss, Gesichtsfeldausfälle","Plötzlicher Hörverlust","Priapismus (schmerzhafte Dauererektion über 4 Stunden)"],"unbekannt":["Stevens-Johnson-Syndrom, exfoliative Dermatitis (schwere Hautreaktionen)","Instabile Angina pectoris, ventrikuläre Herzrhythmusstörungen","Chorioretinopathia centralis serosa (Flüssigkeit unter der Netzhaut)"]},"schwangerschaft":"Vorsichtshalber nicht anwenden (Lungenhochdruck: keine ausreichenden Daten). Für Frauen ist die Behandlung von Erektionsstörungen nicht vorgesehen.","stillzeit":"Nicht anwenden – Tadalafil geht im Tierversuch in die Milch über.","hinweise":["Wirkt bis zu 36 Stunden: in dieser Zeit und bis 48 Stunden nach der letzten Dosis keine Nitrate oder «Poppers» – lebensbedrohlicher Blutdruckabfall.","Eine Erektion, die länger als 4 Stunden anhält, ist ein Notfall – sofort ärztliche Hilfe holen.","Einnahme unabhängig von den Mahlzeiten; grössere Mengen Alkohol meiden.","Bei plötzlicher Sehverschlechterung oder plötzlichem Hörverlust sofort absetzen und ärztlich abklären lassen."],"darreichung":["Filmtabletten"]},"tamoxifen":{"wirkmechanismus":"Verhindert, dass Östrogen das Wachstum von Brustkrebszellen anregt. Tamoxifen bindet an den Östrogenrezeptor und wirkt im Brustgewebe als Gegenspieler, an Gebärmutter, Knochen und Blutgerinnung dagegen teilweise östrogenartig. Es ist ein Prodrug: Über CYP2D6 und CYP3A4 entsteht der hauptsächlich wirksame Metabolit Endoxifen. Bei stark verminderter CYP2D6-Aktivität (genetisch oder durch Hemmer) kann die Wirkung schwächer sein.","nebenwirkungen":{"sehrHaeufig":["Hitzewallungen","Übelkeit","Flüssigkeitseinlagerungen (Ödeme)","Scheidenblutungen oder Ausfluss","Hautausschlag","Müdigkeit"],"haeufig":["Thrombosen und Lungenembolie","Ischämischer Schlaganfall","Grauer Star (Katarakt), Netzhautveränderungen","Gebärmuttermyome, Polypen der Gebärmutterschleimhaut","Erhöhte Triglyceride, Fettleber, erhöhte Leberwerte","Kopfschmerzen, Wadenkrämpfe, Muskelschmerzen","Haarausfall","Anämie, Überempfindlichkeitsreaktionen"],"gelegentlich":["Gebärmutterkrebs (Endometriumkarzinom)","Hyperkalzämie bei Knochenmetastasen","Interstitielle Pneumonitis","Leukopenie, Thrombozytopenie","Pankreatitis"],"selten":["Uterussarkom","Agranulozytose, Neutropenie","Sehnerventzündung","Hepatitis, Cholestase, Leberversagen","Stevens-Johnson-Syndrom und andere schwere Hautreaktionen","Angioödem","Tumorschmerz zu Beginn (Flare)"],"sehrSelten":["Kutaner Lupus erythematodes"]},"schwangerschaft":"Kontraindiziert. Vor Beginn Schwangerschaft ausschliessen; während und noch mehrere Monate nach der Behandlung zuverlässig, aber nicht hormonell verhüten.","stillzeit":"Nicht stillen; Tamoxifen kann zudem die Milchbildung hemmen.","hinweise":["Täglich zur gleichen Zeit einnehmen, meist über 5–10 Jahre; nicht eigenmächtig absetzen.","Ungewöhnliche Blutungen aus der Scheide, Beinschwellung, Atemnot oder Sehstörungen sofort melden; jährliche gynäkologische Kontrolle.","Vor neuen Medikamenten, besonders Antidepressiva, Rücksprache halten (Paroxetin, Fluoxetin meiden)."],"darreichung":["Tabletten","Filmtabletten"]},"tamsulosin":{"wirkmechanismus":"Erleichtert das Wasserlösen, indem es die Muskulatur in Prostata, Blasenhals und Harnröhre entspannt. Tamsulosin blockiert bevorzugt die Alpha-1A- und Alpha-1D-Adrenozeptoren, die in Prostata und Blase überwiegen; dadurch sinkt der Widerstand beim Harnabfluss, der Harnstrahl wird kräftiger und Reizbeschwerden wie häufiger Harndrang nehmen ab. Die Prostata wird dabei nicht kleiner. Wegen der Bevorzugung der Rezeptoren im Harntrakt sinkt der Blutdruck meist nur wenig.","nebenwirkungen":{"haeufig":["Schwindel","Ejakulationsstörungen (verminderter oder fehlender Samenerguss, Samenerguss in die Blase)"],"gelegentlich":["Kopfschmerzen","Herzklopfen","Orthostatische Hypotonie (Blutdruckabfall beim Aufstehen)","Schnupfen, verstopfte Nase","Verstopfung, Durchfall, Übelkeit, Erbrechen","Hautausschlag, Juckreiz, Nesselsucht","Asthenie (Schwäche)"],"selten":["Synkope (Ohnmacht)","Angioödem (Schwellung von Gesicht, Lippen, Zunge)"],"sehrSelten":["Priapismus (schmerzhafte Dauererektion)","Stevens-Johnson-Syndrom (schwere Hautreaktion)"],"unbekannt":["Intraoperatives Floppy-Iris-Syndrom bei Katarakt- oder Glaukomoperation","Verschwommenes Sehen, Sehstörungen","Nasenbluten","Mundtrockenheit","Erythema multiforme, exfoliative Dermatitis (schwere Hautreaktionen)"]},"schwangerschaft":"Nicht für Frauen bestimmt.","stillzeit":"Nicht für Frauen bestimmt.","hinweise":["Einmal täglich unzerkaut schlucken; Retardkapseln nach dem Frühstück, Retardtabletten (Pradif T) unabhängig von den Mahlzeiten.","Vor allem zu Beginn kann Schwindel auftreten: langsam aufstehen und vorsichtig sein beim Autofahren.","Vor einer Augenoperation am grauen oder grünen Star die Einnahme angeben – auch wenn Tamsulosin früher eingenommen wurde.","In der Kombination mit Dutasterid (Duodart) gelten zusätzlich die Hinweise zu Dutasterid."],"darreichung":["Retardtabletten","Retardkapseln"]},"tapentadol":{"wirkmechanismus":"Lindert starke Schmerzen über zwei sich ergänzende Wege in einem Wirkstoff. Tapentadol ist ein Agonist am μ-Opioidrezeptor und hemmt gleichzeitig die Wiederaufnahme von Noradrenalin, wodurch absteigende schmerzhemmende Nervenbahnen im Rückenmark verstärkt werden. Die Opioidwirkung ist dadurch für eine vergleichbare Schmerzlinderung geringer, was sich etwa in weniger Magen-Darm-Beschwerden zeigen kann. Der Abbau erfolgt überwiegend durch Glucuronidierung ohne wirksame Abbauprodukte und mit geringer Beteiligung von CYP-Enzymen.","nebenwirkungen":{"sehrHaeufig":["Schwindel, Schläfrigkeit, Kopfschmerzen","Übelkeit","Obstipation (Verstopfung)"],"haeufig":["Appetitlosigkeit","Angst, gedrückte Stimmung, Schlafstörungen, Unruhe","Konzentrationsstörungen, Zittern, Muskelzuckungen","Hitzegefühl (Flushing)","Atemnot","Erbrechen, Durchfall, Verdauungsbeschwerden","Juckreiz, Schwitzen, Hautausschlag","Müdigkeit, Schwäche, Wassereinlagerungen"],"gelegentlich":["Verwirrtheit, Euphorie, Wahrnehmungsstörungen","Bewusstseinsstörungen, Ohnmacht","Sehstörungen","Herzrasen oder langsamer Puls, Blutdruckabfall","Nesselsucht","Sexuelle Funktionsstörungen","Entzugssymptome"],"selten":["Anaphylaxie, Angioödem (schwere allergische Reaktionen)","Abhängigkeit","Krampfanfälle","Atemdepression (abgeschwächte Atmung)"],"unbekannt":["Delir","Serotonin-Syndrom (in Kombination mit serotonergen Mitteln)"]},"schwangerschaft":"Nur wenn der Nutzen das Risiko klar überwiegt. Längere Anwendung kann beim Neugeborenen ein Entzugssyndrom, Anwendung unter der Geburt eine Atemdepression auslösen.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Retardtabletten ganz schlucken, nicht zerkauen oder zerkleinern.","Kein Alkohol; die Fahrtüchtigkeit ist vor allem zu Beginn und bei Dosisänderungen eingeschränkt.","Nach längerer Anwendung nicht abrupt absetzen, sondern schrittweise reduzieren (Entzugssymptome)."],"darreichung":["Filmtabletten","Retardtabletten"]},"teduglutid":{"wirkmechanismus":"Fördert das Wachstum und die Erholung der verbliebenen Darmschleimhaut, damit mehr Flüssigkeit und Nährstoffe aufgenommen werden. Teduglutid ist ein gentechnisch hergestelltes Analogon des körpereigenen Darmhormons GLP-2 und bindet an GLP-2-Rezeptoren im Darm. Dies vergrössert Darmzotten und Krypten, verbessert die Durchblutung und verlangsamt Magenentleerung und Darmpassage. Durch einen Aminosäureaustausch wird es vom Enzym DPP-4 kaum abgebaut und wirkt deshalb länger als natürliches GLP-2.","nebenwirkungen":{"sehrHaeufig":["Atemwegsinfektionen","Kopfschmerzen","Bauchschmerzen und Blähbauch","Übelkeit, Erbrechen","Schwellung oder andere Veränderungen am Stoma (künstlicher Darmausgang)","Reaktionen an der Injektionsstelle"],"haeufig":["Grippeähnliche Beschwerden","Appetitminderung","Flüssigkeitsüberladung, periphere Ödeme","Angst, Schlafstörungen","Kolorektale Polypen (Dickdarmpolypen)","Darmverschluss oder Darmverengung","Pankreatitis (Bauchspeicheldrüsenentzündung)","Cholezystitis (Gallenblasenentzündung)"],"unbekannt":["Magen- und Zwölffingerdarmpolypen","Überempfindlichkeitsreaktionen"]},"schwangerschaft":"Vorsichtshalber in der Schwangerschaft vermeiden.","stillzeit":"Ein Risiko für den Säugling ist nicht auszuschliessen; über Stillen oder Behandlung wird nach ärztlicher Abwägung entschieden.","hinweise":["Einmal täglich unter die Haut von Bauch oder Oberschenkel spritzen, Einstichstelle wechseln.","Bei starken Bauchschmerzen, Blähbauch, Erbrechen oder Schwellung am Stoma sofort ärztlichen Rat einholen.","Gewicht, Flüssigkeitshaushalt und Laborwerte werden regelmässig kontrolliert, v. a. bei Anpassung der parenteralen Ernährung."],"darreichung":["Pulver und Lösungsmittel zur Herstellung einer Injektionslösung"]},"telmisartan":{"wirkmechanismus":"Senkt den Blutdruck, indem es die Wirkung des gefässverengenden Hormons Angiotensin II blockiert. Telmisartan bindet selektiv und lang anhaltend an den Angiotensin-II-Rezeptor Typ 1 (AT1) und hebt so die gefässverengende und aldosteronfreisetzende Wirkung von Angiotensin II auf: Die Gefässe erweitern sich, Salz- und Wasserrückhaltung nehmen ab. Anders als ACE-Hemmer hemmt es den Abbau von Bradykinin nicht, weshalb trockener Reizhusten selten ist. Telmisartan wird fast vollständig über die Galle ausgeschieden und wirkt dank langer Halbwertszeit (rund 24 Stunden) über den ganzen Tag.","nebenwirkungen":{"gelegentlich":["Hypotonie (tiefer Blutdruck), auch beim Aufstehen – bei Behandlung zur Herz-Kreislauf-Vorbeugung häufig","Hyperkaliämie (erhöhtes Kalium)","Nierenfunktionsstörung bis zum akuten Nierenversagen, erhöhtes Kreatinin","Synkope (kurze Ohnmacht), Vertigo (Drehschwindel), Bradykardie (langsamer Puls)","Harnwegsinfekte und Infekte der oberen Atemwege (z. B. Rachenentzündung, Sinusitis)","Bauchschmerzen, Durchfall, Verdauungsbeschwerden, Blähungen, Erbrechen","Muskelschmerzen, Muskelkrämpfe, Rückenschmerzen","Anämie (Blutarmut)"],"selten":["Angioödem (Schwellung von Gesicht, Zunge oder Rachen), auch lebensbedrohlich","Anaphylaxie (schwere allergische Reaktion)","Sepsis (Blutvergiftung), auch mit tödlichem Verlauf","Hypoglykämie (Unterzuckerung) bei Diabetikern","Thrombozytopenie (Mangel an Blutplättchen), Eosinophilie","Leberfunktionsstörung, erhöhte Leberwerte","Hautausschläge (Ekzem, Nesselsucht, toxischer Hautausschlag)","Gelenk- und Sehnenschmerzen"],"sehrSelten":["Interstitielle Lungenerkrankung"]},"schwangerschaft":"Im 1. Drittel nicht empfohlen, im 2. und 3. Drittel kontraindiziert (Schäden an Nieren und Schädelknochen des Ungeborenen, Fruchtwassermangel). Bei Kinderwunsch oder festgestellter Schwangerschaft rasch auf ein geeignetes Mittel umstellen.","stillzeit":"Nicht empfohlen, da Daten fehlen; besser untersuchte Alternativen wählen, besonders bei Neu- und Frühgeborenen.","hinweise":["Einmal täglich, mit oder ohne Essen; die volle Blutdrucksenkung wird nach 4–8 Wochen erreicht.","Kalium und Nierenwerte zu Beginn und regelmässig kontrollieren lassen.","Bei Durchfall, Erbrechen oder starkem Schwitzen ärztlich Rücksprache nehmen – Gefahr von Blutdruckabfall und Nierenversagen.","Zu Beginn können Schwindel und Müdigkeit die Fahrtüchtigkeit beeinträchtigen."],"darreichung":["Tabletten"]},"telotristat":{"wirkmechanismus":"Vermindert die übermässige Bildung von Serotonin, die beim Karzinoidsyndrom Durchfall verursacht. Telotristat ethyl ist eine Vorstufe, die im Körper zum aktiven Telotristat umgewandelt wird. Dieses hemmt die Tryptophanhydroxylase, das Schlüsselenzym der Serotoninbildung aus Tryptophan in Tumor- und Darmzellen. Dadurch sinken Serotoninspiegel und Stuhlfrequenz; ins Gehirn gelangt der Wirkstoff kaum.","nebenwirkungen":{"sehrHaeufig":["Bauchschmerzen","Müdigkeit"],"haeufig":["Appetitminderung","Depression, gedrückte Stimmung","Kopfschmerzen","Blähbauch, Blähungen, Verstopfung","Erhöhte Leberwerte (GGT, Transaminasen, alkalische Phosphatase)","Periphere Ödeme (Wassereinlagerungen)","Fieber"],"gelegentlich":["Kotstau (Fäkalom)"]},"schwangerschaft":"Nicht empfohlen; Frauen im gebärfähigen Alter müssen wirksam verhüten.","stillzeit":"Ein Risiko für den Säugling ist nicht auszuschliessen; Stillen während der Behandlung nicht empfohlen.","hinweise":["Dreimal täglich mit einer Mahlzeit oder einem Imbiss einnehmen.","Die Behandlung mit dem Somatostatin-Analogon (z. B. Octreotid, Lanreotid) weiterführen.","Verstopfung, zunehmende Bauchschmerzen oder gedrückte Stimmung ärztlich melden."],"darreichung":["Filmtabletten"]},"temozolomid":{"wirkmechanismus":"Hemmt das Wachstum von Hirntumorzellen, indem es deren Erbgut schädigt. Temozolomid ist ein Prodrug, das ohne Leberstoffwechsel beim pH-Wert des Körpers spontan zum aktiven Methyltriazen MTIC zerfällt. MTIC hängt Methylgruppen an die DNA-Base Guanin (vor allem an der O6- und N7-Position); die entstehenden Fehlpaarungen lösen den Zelltod aus. Tumoren, deren Reparaturenzym MGMT abgeschaltet ist (methylierter MGMT-Promotor), sprechen besonders gut an; der Wirkstoff gelangt gut ins Gehirn.","nebenwirkungen":{"sehrHaeufig":["Übelkeit, Erbrechen","Verstopfung","Appetitlosigkeit","Müdigkeit","Kopfschmerzen","Haarausfall","Hautausschlag"],"haeufig":["Mangel an Blutplättchen, weissen und roten Blutkörperchen (Thrombozytopenie, Neutropenie, Lymphopenie, Anämie)","Infektionen, Mundsoor (Pilzbefall)","Krampfanfälle","Schwindel, Gedächtnis- und Konzentrationsstörungen, Verwirrtheit","Schlafstörungen, Angst","Durchfall, Bauchschmerzen, Mundschleimhautentzündung","Atemnot, Husten","Erhöhte Leberwerte"],"unbekannt":["Pneumocystis-Pneumonie und andere opportunistische Infektionen (z. B. Zytomegalie, Hepatitis-B-Reaktivierung)","Lang anhaltender Mangel aller Blutzellen, aplastische Anämie","Myelodysplastisches Syndrom und Zweitleukämien","Leberschäden bis Leberversagen","Interstitielle Pneumonitis, Lungenfibrose","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)","Anaphylaxie (schwere allergische Reaktion)","Diabetes insipidus"]},"schwangerschaft":"Nicht anwenden (im Tierversuch fruchtschädigend). Frauen und Männer müssen während und bis mehrere Monate nach der Behandlung zuverlässig verhüten.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Kapseln nüchtern (mindestens 1 Stunde vor einer Mahlzeit) unzerkaut mit Wasser schlucken; nicht öffnen – bei Kontakt mit dem Inhalt Haut sofort waschen.","Vorbeugend Mittel gegen Übelkeit einnehmen; bei Erbrechen am selben Tag keine zweite Dosis nehmen.","Blutbild- und Leberkontrollen vor und während jedes Zyklus; Fieber und Infektzeichen sofort melden."],"darreichung":["Hartkapseln"]},"tenofoviralafenamid":{"wirkmechanismus":"Hemmt die Vermehrung des Hepatitis-B-Virus und von HIV. Tenofoviralafenamid ist eine im Blut stabile Vorstufe von Tenofovir, die vor allem in Leberzellen und Lymphozyten aufgenommen und dort (durch Carboxylesterase 1 bzw. Cathepsin A) zu Tenofovir gespalten wird. Tenofovir wird zum aktiven Tenofovir-Diphosphat phosphoryliert, das in die Virus-DNA eingebaut wird und die Kettenverlängerung abbricht. Weil eine kleine Dosis genügt, ist der Tenofovir-Spiegel im Blut rund 90 % tiefer als mit Tenofovirdisoproxil – Nieren und Knochen werden weniger belastet.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen"],"haeufig":["Schwindel","Übelkeit, Erbrechen, Durchfall","Bauchschmerzen, Blähbauch, Blähungen","Erhöhte Leberwerte (ALT)","Hautausschlag, Juckreiz","Gelenkschmerzen","Müdigkeit"],"gelegentlich":["Angioödem (Schwellung von Haut und Schleimhäuten)","Nesselsucht"],"unbekannt":["Schwere Hepatitisschübe nach dem Absetzen"]},"schwangerschaft":"Kann bei Bedarf in der Schwangerschaft in Betracht gezogen werden; die bisherigen Daten zeigen kein erhöhtes Fehlbildungsrisiko.","stillzeit":"Gemäss Fachinformation nicht stillen, da Tenofovir in die Muttermilch übergeht und ein Risiko für das Kind nicht ausgeschlossen ist. HIV-positive Mütter sollen grundsätzlich nicht stillen.","hinweise":["Einmal täglich mit einer Mahlzeit einnehmen.","Bei Hepatitis B nicht eigenmächtig absetzen – nach dem Absetzen Leberwerte über Monate kontrollieren.","Vor Beginn HIV-Test; Nierenfunktion regelmässig kontrollieren lassen."],"darreichung":["Filmtabletten"]},"tenofovirdisoproxil":{"wirkmechanismus":"Hemmt die Vermehrung von HIV und Hepatitis-B-Viren. Tenofovirdisoproxil ist eine Vorstufe (Prodrug), die nach der Aufnahme zu Tenofovir gespalten und in den Zellen zu Tenofovir-Diphosphat aktiviert wird. Dieses Nukleotid-Analogon des Adenosins wird von der Reversen Transkriptase von HIV bzw. der Polymerase des Hepatitis-B-Virus in die Virus-DNA eingebaut und führt zum Kettenabbruch. Tenofovir wird über die Nieren ausgeschieden und reichert sich in den Zellen der Nierenkanälchen an, was die mögliche Nierenschädigung erklärt.","nebenwirkungen":{"sehrHaeufig":["Hypophosphatämie (zu wenig Phosphat im Blut)","Schwindel","Durchfall, Übelkeit, Erbrechen","Hautausschlag","Asthenie (Schwäche)"],"haeufig":["Kopfschmerzen","Bauchschmerzen, Blähbauch, Blähungen","Erhöhte Leberwerte","Müdigkeit"],"gelegentlich":["Proximale Tubulopathie der Niere (inkl. Fanconi-Syndrom), Kreatininanstieg","Hypokaliämie (Kaliummangel)","Pankreatitis (Bauchspeicheldrüsenentzündung)","Rhabdomyolyse (Muskelzerfall), Muskelschwäche"],"selten":["Akutes Nierenversagen, Nierenentzündung, nephrogener Diabetes insipidus","Osteomalazie (Knochenerweichung) mit Knochenschmerzen und Brüchen","Laktatazidose (Übersäuerung des Blutes)","Fettleber, Hepatitis","Angioödem (Schwellung von Haut und Schleimhäuten)"]},"schwangerschaft":"Kann bei Bedarf in der Schwangerschaft angewendet werden; umfangreiche Daten zeigen kein erhöhtes Fehlbildungsrisiko.","stillzeit":"Tenofovir geht in die Muttermilch über; gemäss Fachinformation während der Stillzeit nicht anwenden. HIV-positive Mütter sollen grundsätzlich nicht stillen.","hinweise":["Mit einer Mahlzeit einnehmen (bessere Aufnahme).","Nierenwerte und Phosphat vor Beginn und regelmässig während der Behandlung kontrollieren lassen.","Bei Hepatitis B nicht eigenmächtig absetzen – Hepatitisschub möglich.","Regelmässige Einnahme von Schmerzmitteln wie Ibuprofen oder Diclofenac vorher mit der Fachperson besprechen."],"darreichung":["Filmtabletten"]},"terbinafin":{"wirkmechanismus":"Tötet Pilze ab, indem es den Aufbau ihrer Zellmembran stört. Terbinafin hemmt gezielt das pilzeigene Enzym Squalen-Epoxidase: Dadurch fehlt der Membranbaustein Ergosterol, und gleichzeitig reichert sich Squalen in giftigen Mengen in der Pilzzelle an. Gegen Dermatophyten (Fadenpilze) wirkt es abtötend (fungizid), gegen Hefen teils nur wachstumshemmend. Nach Einnahme reichert sich Terbinafin in Haut, Haaren und Nägeln an und bleibt dort über Wochen wirksam.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen (Tabletten)","Magen-Darm-Beschwerden wie Völlegefühl, Appetitlosigkeit, Dyspepsie (Verdauungsbeschwerden), Übelkeit, leichte Bauchschmerzen, Durchfall (Tabletten)","Hautausschlag, Nesselsucht (Tabletten)","Gelenk- und Muskelschmerzen (Tabletten)"],"haeufig":["Geschmacksstörung oder Geschmacksverlust, teils lang anhaltend (Tabletten)","Schwindel, Müdigkeit (Tabletten)","Sehstörungen (Tabletten)","Depressive Verstimmung (Tabletten)","Hautschuppung und Juckreiz an der Auftragsstelle (Creme, Gel)"],"gelegentlich":["Kribbeln oder Taubheitsgefühl (Parästhesien)","Ohrgeräusche (Tinnitus)","Lichtempfindlichkeit der Haut (Photosensibilität)","Angst, Fieber, Gewichtsabnahme","Rötung, Brennen oder Reizung an der Auftragsstelle (Creme, Gel)"],"selten":["Leberschäden: Hepatitis, Gallestau, Gelbsucht, erhöhte Leberwerte, Leberversagen (Einzelfälle mit Lebertransplantation oder tödlichem Verlauf)","Augenreizung, trockene Haut, Kontaktekzem (äusserliche Anwendung)"],"sehrSelten":["Agranulozytose, Neutropenie, Thrombozytopenie, Panzytopenie (schwere Blutbildstörungen)","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, akute generalisierte exanthematische Pustulose)","Auslösung oder Verschlechterung einer Psoriasis","Lupus erythematodes (Haut oder ganzer Körper)","Anaphylaktoide Reaktionen, Angioödem (Schwellung von Haut und Schleimhäuten)","Haarausfall"],"unbekannt":["DRESS (schwere Arzneimittelreaktion mit Fieber, Ausschlag und Organbeteiligung)","Pankreatitis (Bauchspeicheldrüsenentzündung)","Geruchsverlust, Hörminderung","Vaskulitis (Gefässentzündung)","Rhabdomyolyse (Muskelzerfall)","Serumkrankheit-ähnliche Reaktion, grippeähnliche Beschwerden"]},"schwangerschaft":"Tabletten: nicht anwenden, ausser wenn eindeutig notwendig (ungenügende Erfahrung). Creme, Gel und Lösung nur nach ärztlicher Abwägung; die Aufnahme über die Haut ist gering.","stillzeit":"Terbinafin geht in die Muttermilch über: während der Einnahme von Tabletten nicht stillen. Äusserliche Mittel nicht auf die Brust auftragen; der Säugling soll nicht mit behandelter Haut in Kontakt kommen.","hinweise":["Vor einer Tablettenbehandlung Leberwerte bestimmen lassen; bei Übelkeit, Appetitverlust, Müdigkeit, Gelbfärbung der Haut oder Augen, dunklem Urin oder hellem Stuhl sofort Arzt kontaktieren.","Bei Nagelpilz wächst der gesunde Nagel erst Monate nach Ende der Tabletteneinnahme nach – der Erfolg zeigt sich verzögert.","Geschmacksstörungen können nach dem Absetzen noch Wochen anhalten; bei Appetit- oder Gewichtsverlust den Arzt informieren.","Die Wechselwirkungen betreffen die Tabletten; Lamisil Once wird nur einmal auf beide Füsse aufgetragen, auch wenn nur ein Fuss betroffen ist."],"darreichung":["Tabletten","Creme","Gel","Lösung zur Anwendung auf der Haut (Einmalanwendung)"]},"teriparatid":{"wirkmechanismus":"Regt die knochenbildenden Zellen an und baut so neue Knochensubstanz auf – im Gegensatz zu den meisten Osteoporosemitteln, die nur den Knochenabbau bremsen. Teriparatid ist das gentechnisch hergestellte aktive Teilstück (Aminosäuren 1–34) des körpereigenen Parathormons und bindet an den PTH-1-Rezeptor. Einmal täglich gegeben, stimuliert es überwiegend die Osteoblasten (osteoanaboler Effekt), während ein dauerhaft erhöhtes Parathormon den Knochen abbauen würde. Knochendichte und -struktur nehmen vor allem an der Wirbelsäule zu, das Risiko für Wirbel- und andere Brüche sinkt. Zudem steigert es vorübergehend die Calciumaufnahme im Darm und die Calcium-Rückresorption in der Niere.","nebenwirkungen":{"sehrHaeufig":["Gliederschmerzen"],"haeufig":["Übelkeit, Erbrechen, Sodbrennen","Kopfschmerzen, Schwindel, Drehschwindel","Blutdruckabfall, kurze Bewusstlosigkeit (Synkope), Herzklopfen","Muskelkrämpfe, Ischiasschmerzen","Müdigkeit, Schwäche, Brustschmerzen, Atemnot","Depression","Leichte Reaktionen an der Einstichstelle (Schmerz, Schwellung, Rötung, Juckreiz)","Anämie (Blutarmut), erhöhtes Cholesterin, vermehrtes Schwitzen"],"gelegentlich":["Hyperkalzämie (Calcium im Blut über 2,76 mmol/l)","Erhöhte Harnsäure","Schneller Puls (Tachykardie)","Nierensteine, häufiger Harndrang, Harninkontinenz","Muskel-, Gelenk- und Rückenschmerzen","Gewichtszunahme, erhöhte alkalische Phosphatase"],"selten":["Allergische Reaktionen bis zur Anaphylaxie, meist kurz nach der Injektion","Stark erhöhtes Calcium (über 3,25 mmol/l)","Nierenfunktionsstörung","Wassereinlagerungen (Ödeme)"],"unbekannt":["Osteosarkom (Knochenkrebs): in Tierversuchen gehäuft, beim Menschen nur sehr vereinzelt berichtet"]},"schwangerschaft":"Kontraindiziert. Frauen im gebärfähigen Alter müssen während der Behandlung wirksam verhüten; bei einer Schwangerschaft wird Teriparatid abgesetzt.","stillzeit":"Kontraindiziert (nicht bekannt, ob Teriparatid in die Muttermilch übergeht).","hinweise":["Einmal täglich in Oberschenkel oder Bauch spritzen, möglichst immer zur gleichen Tageszeit; den Pen im Kühlschrank lagern.","Die ersten Injektionen im Sitzen oder Liegen verabreichen – Schwindel durch Blutdruckabfall möglich; bei Schwindel nicht Auto fahren.","Gesamtdauer höchstens 24 Monate; danach wird meist mit einem knochenabbauhemmenden Mittel weiterbehandelt, damit der Gewinn an Knochenmasse erhalten bleibt.","Anhaltende Übelkeit, Verstopfung, Müdigkeit oder Muskelschwäche (mögliche Zeichen eines zu hohen Calciums) ärztlich melden."],"darreichung":["Injektionslösung im Fertigpen (zur Injektion unter die Haut)"]},"terlipressin":{"wirkmechanismus":"Verengt die Blutgefässe im Bauchraum und senkt so den Druck in den Krampfadern der Speiseröhre. Terlipressin ist eine Vorstufe (Prodrug), aus der im Körper langsam Lysin-Vasopressin freigesetzt wird. Dieses wirkt über Vasopressin-V1-Rezeptoren gefässverengend, vor allem im Splanchnikusgebiet, wodurch der Pfortaderdruck sinkt. Beim hepatorenalen Syndrom verbessert die Umverteilung des Blutes die Nierendurchblutung und -funktion.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Bradykardie (langsamer Puls)","Bluthochdruck","Periphere Durchblutungsstörungen, Blässe (kalte Hände und Füsse)","Vorübergehende Bauchkrämpfe, Durchfall"],"gelegentlich":["Herzrhythmusstörungen (Vorhofflimmern, Extrasystolen, Herzrasen)","Brustschmerzen, Herzinfarkt","Lungenödem durch Flüssigkeitsüberladung","Darmischämie (Minderdurchblutung des Darms)","Übelkeit, Erbrechen","Hautnekrose (Absterben von Haut), auch an der Injektionsstelle","Gebärmutterkrämpfe"],"unbekannt":["Atemversagen, Atemnot (v. a. beim hepatorenalen Syndrom)","Torsade de pointes (gefährliche Herzrhythmusstörung), QT-Verlängerung","Herzinsuffizienz","Hyponatriämie (Natriummangel)"]},"schwangerschaft":"Kontraindiziert: Terlipressin löst Gebärmutterkontraktionen aus, vermindert die Durchblutung der Gebärmutter und kann eine Fehlgeburt verursachen.","stillzeit":"Nicht bekannt, ob Terlipressin in die Muttermilch übergeht; Anwendung nur nach ärztlicher Abwägung.","hinweise":["Wird nur im Spital unter Überwachung von Blutdruck, Puls, EKG, Sauerstoffsättigung, Flüssigkeitshaushalt und Elektrolyten angewendet.","Atemnot, Brustschmerzen oder Schmerzen in Bauch, Händen oder Füssen sofort dem Behandlungsteam melden.","Beim hepatorenalen Syndrom wird die Albumin-Gabe angepasst, um eine Flüssigkeitsüberladung zu vermeiden."],"darreichung":["Injektionslösung","Pulver und Lösungsmittel zur Herstellung einer Injektionslösung"]},"testosteron":{"wirkmechanismus":"Ersetzt das körpereigene männliche Geschlechtshormon, wenn die Hoden zu wenig davon bilden. Testosteron bindet an Androgenrezeptoren, teils direkt, teils nach Umwandlung durch die 5-Alpha-Reduktase in das stärker wirksame Dihydrotestosteron; ein Teil wird durch Aromatase in Estradiol umgewandelt. Es fördert männliche Geschlechtsmerkmale, Libido und Potenz, Muskelmasse, Knochendichte und die Bildung roter Blutkörperchen. Als Ester (Undecanoat, Enantat) in öliger Lösung wird es aus dem Muskel langsam freigesetzt; das Gel wird über die Haut aufgenommen.","nebenwirkungen":{"haeufig":["Erhöhter Hämatokrit und Hämoglobin (zu viele rote Blutkörperchen, Polyzythämie)","Akne","Gewichtszunahme","Hitzewallungen","Anstieg des PSA-Werts, Prostataveränderungen","Reaktionen an der Einstich- oder Auftragsstelle (Schmerzen, Bluterguss, Hautrötung)"],"gelegentlich":["Bluthochdruck","Kopfschmerzen, Schwindel","Stimmungsschwankungen, Depression, Aggressivität, Schlaflosigkeit","Veränderte Libido","Brustvergrösserung (Gynäkomastie), Brustspannen, Hodenschmerzen","Erhöhte Leberwerte, veränderte Blutfette","Wassereinlagerungen (Ödeme)","Haarausfall, Juckreiz, fettige Haut, vermehrtes Schwitzen"],"selten":["Ölmikroembolie der Lunge während oder kurz nach der Depotspritze (Husten, Atemnot, Unwohlsein, Schwindel)","Schwere allergische Reaktionen nach der Injektion"],"unbekannt":["Venöse Thromboembolie (Thrombose, Lungenembolie)","Verminderte Spermienbildung, Verkleinerung der Hoden (vor allem bei hoher Dosis)","Lebertumoren bei langdauernder hoch dosierter Anwendung","Verschlechterung einer Schlafapnoe","Häufige oder schmerzhaft anhaltende Erektionen (Priapismus)"]},"schwangerschaft":"Kontraindiziert: Testosteron kann beim ungeborenen Mädchen eine Vermännlichung verursachen. Schwangere dürfen nicht mit Testosteron-Gel in Hautkontakt kommen.","stillzeit":"Kontraindiziert; Testosteronpräparate sind nicht für Frauen bestimmt.","hinweise":["Vor und während der Behandlung regelmässig Blutbild (Hämatokrit), PSA und Prostata, Leberwerte und Blutfette kontrollieren lassen.","Gel: Nach dem Auftragen Hände waschen und die Stelle nach dem Trocknen mit Kleidung bedecken – Hautkontakt kann Frauen und Kinder vermännlichen.","Nicht zur Leistungssteigerung oder zum Muskelaufbau missbrauchen: Gefahr schwerer Herz-, Leber- und psychischer Schäden; im Sport als Doping verboten.","Hohe Dosen hemmen die Spermienbildung (meist umkehrbar) – bei Kinderwunsch ärztlich besprechen."],"darreichung":["Depot-Injektionslösung (ölig, intramuskulär)","Gel zum Auftragen auf die Haut"]},"tetracosactid":{"wirkmechanismus":"Regt die Nebennierenrinde an, Kortisol zu bilden – so lässt sich prüfen, ob sie normal arbeitet. Tetracosactid entspricht den ersten 24 Aminosäuren des körpereigenen ACTH (Corticotropin) und bindet an die ACTH-Rezeptoren (MC2-Rezeptoren) der Nebennierenrinde. Diese schüttet daraufhin Kortisol und in geringerem Mass Mineralokortikoide und Androgene aus. Bleibt der Kortisolanstieg im Test aus, spricht das für eine Nebenniereninsuffizienz; die Depotform wirkt über die anhaltende Kortisolbildung wie eine Kortisonbehandlung.","nebenwirkungen":{"unbekannt":["Überempfindlichkeitsreaktionen bis Anaphylaxie (Atemnot, Hautausschlag, Kreislaufkollaps)","Reaktionen an der Injektionsstelle","Gesichtsrötung, Schwindel, Übelkeit","Depotform: Wassereinlagerung, Bluthochdruck, erhöhter Blutzucker, Kaliummangel","Depotform: dunklere Hautpigmentierung, Akne","Depotform: psychische Veränderungen (Euphorie, Schlaflosigkeit, Verstimmung)","Depotform: Knochenschwund, erhöhte Infektanfälligkeit"]},"schwangerschaft":"Nur bei klarer Notwendigkeit nach ärztlicher Abwägung; Daten sind begrenzt.","stillzeit":"Nur nach ärztlicher Abwägung.","hinweise":["Wird von Fachpersonen gespritzt; danach mindestens 30 Minuten Überwachung wegen möglicher allergischer Reaktionen.","Vor dem Test angeben, welche Hormon- und Kortisonpräparate eingenommen werden.","Bei der Depotform wie bei einer Kortisonbehandlung Blutdruck, Blutzucker und Kalium kontrollieren."],"darreichung":["Injektionslösung","Depot-Injektionssuspension"]},"thiamin-vitamin-b1":{"wirkmechanismus":"Ersetzt Vitamin B1, das Nerven, Herz und Muskeln für die Energiegewinnung aus Kohlenhydraten brauchen. Im Körper wird Thiamin zu Thiaminpyrophosphat umgewandelt, einem Coenzym der Pyruvat-Dehydrogenase, der Alpha-Ketoglutarat-Dehydrogenase und der Transketolase. Bei Mangel stockt der Zuckerabbau, was vor allem das Nervensystem (Polyneuropathie, Wernicke-Enzephalopathie) und das Herz (Beriberi) schädigt. Der Körper speichert nur wenig Thiamin, sodass bei Alkoholkrankheit, Mangelernährung oder anhaltendem Erbrechen rasch ein Mangel entsteht.","nebenwirkungen":{"sehrSelten":["Überempfindlichkeitsreaktionen mit Schwitzen, Herzrasen, Juckreiz und Nesselsucht","Anaphylaktischer Schock, vor allem nach Injektion"],"unbekannt":["Schmerzen oder Reizung an der Injektionsstelle"]},"schwangerschaft":"In Dosen zur Bedarfsdeckung und zur Behandlung eines nachgewiesenen Mangels erlaubt.","stillzeit":"Erlaubt; Thiamin geht in die Muttermilch über, schadet dem Kind in üblichen Dosen aber nicht.","hinweise":["Bei Alkoholkrankheit und Mangelernährung wird Thiamin vor Glucosegaben verabreicht.","Tabletten unzerkaut mit etwas Flüssigkeit einnehmen.","Bei Atemnot, Schwellungen oder Hautausschlag nach einer Injektion sofort ärztliche Hilfe holen."],"darreichung":["Tabletten","Injektionslösung"]},"thyrotropin-alfa":{"wirkmechanismus":"Stimuliert verbliebene Schilddrüsen- und Schilddrüsenkrebszellen, ohne dass die Schilddrüsenhormone abgesetzt werden müssen. Thyrotropin alfa ist gentechnisch hergestelltes humanes TSH und bindet an die TSH-Rezeptoren von normalem Schilddrüsengewebe und gut differenzierten Schilddrüsenkrebszellen. Diese nehmen dadurch vermehrt radioaktives Jod auf und setzen Thyreoglobulin frei. So sind Nachsorgeuntersuchungen und Radiojod-Ablation ohne die belastende Schilddrüsenunterfunktion durch Hormonentzug möglich.","nebenwirkungen":{"sehrHaeufig":["Übelkeit"],"haeufig":["Erbrechen","Kopfschmerzen, Schwindel","Müdigkeit, Schwäche"],"gelegentlich":["Durchfall","Grippeähnliche Beschwerden, Fieber, Schüttelfrost","Hitzewallungen","Geschmacksstörung, Kribbeln","Hautausschlag, Nesselsucht","Nacken- und Rückenschmerzen"],"unbekannt":["Schwellung oder Schmerzen von Tumoren bzw. Metastasen","Schlaganfall","Herzklopfen","Überempfindlichkeitsreaktionen","Zittern"]},"schwangerschaft":"Kontraindiziert.","stillzeit":"Während der Anwendung nicht stillen; bei einer Radiojodbehandlung muss ohnehin abgestillt werden.","hinweise":["Zwei Injektionen in den Gesässmuskel im Abstand von 24 Stunden; nie in die Vene.","Die Schilddrüsenhormone werden normal weiter eingenommen.","Neue neurologische Beschwerden (z. B. Lähmungen, Sprachstörungen) oder Schwellungen im Halsbereich sofort melden."],"darreichung":["Pulver zur Herstellung einer Injektionslösung"]},"tibolon":{"wirkmechanismus":"Lindert Wechseljahresbeschwerden, indem es im Körper in mehrere hormonähnlich wirkende Stoffe umgewandelt wird. Die Metaboliten 3-alpha- und 3-beta-Hydroxytibolon wirken östrogen (gegen Hitzewallungen und Knochenabbau), das Delta-4-Isomer wirkt gestagen und androgen. Die gestagene Wirkung auf die Gebärmutterschleimhaut macht einen zusätzlichen Gestagenschutz überflüssig.","nebenwirkungen":{"haeufig":["Unterleibs- und Beckenschmerzen","Vaginale Blutungen oder Schmierblutungen","Verdickung der Gebärmutterschleimhaut","Brustspannen","Vaginale Pilzinfektion, Ausfluss, Juckreiz im Genitalbereich","Vermehrte Körperbehaarung","Gewichtszunahme","Auffälliger Krebsabstrich (Zervixdysplasie)"],"gelegentlich":["Akne","Brustbeschwerden, Brustwarzenschmerzen","Wassereinlagerungen (Ödeme)","Pilzinfektionen"],"unbekannt":["Schlaganfall, venöse Thromboembolie","Brustkrebs, Gebärmutterschleimhautkrebs","Kopfschmerzen, Migräne, Schwindel, Depression","Sehstörungen","Hautausschlag, Juckreiz","Gelenk- und Muskelschmerzen","Veränderte Leberwerte"]},"schwangerschaft":"Kontraindiziert. Tritt eine Schwangerschaft ein, sofort absetzen.","stillzeit":"Kontraindiziert.","hinweise":["Frühestens 12 Monate nach der letzten natürlichen Menstruation beginnen, sonst sind unregelmässige Blutungen häufig; Tibolon verhütet nicht.","Täglich zur gleichen Zeit einnehmen; ein zusätzliches Gestagen ist nicht nötig.","Blutungen nach mehr als 6 Monaten Anwendung oder nach Absetzen ärztlich abklären lassen.","Wer Blutverdünner wie Phenprocoumon oder Acenocoumarol einnimmt, braucht anfangs engmaschige INR-Kontrollen."],"darreichung":["Tabletten"]},"ticagrelor":{"wirkmechanismus":"Verhindert, dass Blutplättchen verklumpen und Gerinnsel in den Herzkranzgefässen bilden. Ticagrelor blockiert den ADP-Rezeptor P2Y12 der Blutplättchen direkt und reversibel; es muss nicht erst in der Leber aktiviert werden und wirkt deshalb rasch und unabhängig vom CYP2C19-Stoffwechsel. Weil die Bindung umkehrbar ist, lässt die Wirkung nach dem Absetzen innerhalb weniger Tage nach. Zusätzlich hemmt Ticagrelor die Wiederaufnahme von Adenosin, was die häufige Atemnot erklären könnte. Der Abbau erfolgt über CYP3A4.","nebenwirkungen":{"sehrHaeufig":["Blutungen (z. B. Blutergüsse, Nasenbluten)","Dyspnoe (Atemnot, meist leicht und vorübergehend)","Hyperurikämie (erhöhte Harnsäure)"],"haeufig":["Gicht","Schwindel, Kopfschmerzen, Ohnmacht","Tiefer Blutdruck","Magen-Darm-Blutungen und Blutungen der Atemwege","Durchfall, Übelkeit, Verdauungsbeschwerden, Verstopfung","Hautausschlag, Juckreiz, Hautblutungen","Blutungen der Harnwege, erhöhtes Kreatinin","Nachblutungen nach Eingriffen und nach Verletzungen"],"gelegentlich":["Hirnblutung","Überempfindlichkeitsreaktionen einschliesslich Angioödem","Verwirrtheit","Augen- und Ohrenblutungen","Blutungen im hinteren Bauchraum (retroperitoneal), Muskelblutungen","Blutungen aus Tumoren"],"unbekannt":["Thrombotisch-thrombozytopenische Purpura (TTP)","Bradyarrhythmie (zu langsamer Herzschlag, Rhythmuspausen)","Zentrale Schlafapnoe einschliesslich Cheyne-Stokes-Atmung"]},"schwangerschaft":"Nicht empfohlen; Frauen im gebärfähigen Alter sollen während der Behandlung sicher verhüten.","stillzeit":"Ticagrelor geht im Tierversuch in die Milch über; Stillen oder Behandlung abbrechen – ärztlich entscheiden.","hinweise":["Nicht eigenmächtig absetzen – erhöhtes Risiko für Herzinfarkt, Stentverschluss und Tod.","Atemnot ist häufig und meist harmlos; bei starker oder zunehmender Atemnot ärztlich abklären lassen.","Vor Operationen und Zahnbehandlungen die Einnahme angeben; ein Pausieren (meist 5 Tage vorher) nur nach ärztlicher Anordnung.","Tabletten dürfen zerstossen und in Wasser eingenommen werden; neue Medikamente (auch Antibiotika, Pilzmittel, Johanniskraut) in der Apotheke prüfen lassen."],"darreichung":["Filmtabletten"]},"tilidin-naloxon":{"wirkmechanismus":"Lindert starke Schmerzen über die körpereigenen Opioid-Andockstellen in Gehirn und Rückenmark. Tilidin ist eine Vorstufe (Prodrug), die in der Leber zum eigentlichen Wirkstoff Nortilidin umgewandelt wird; dieses wirkt als Agonist am μ-Opioidrezeptor. Naloxon ist ein Opioid-Antagonist, der beim Schlucken in üblicher Dosis in der Leber fast vollständig abgebaut wird und die Schmerzlinderung kaum beeinflusst. Bei Injektion oder sehr hohen Dosen blockiert Naloxon jedoch die Opioidwirkung und kann bei Opioidabhängigen einen Entzug auslösen.","nebenwirkungen":{"sehrHaeufig":["Übelkeit"],"haeufig":["Erbrechen","Schwindel, Benommenheit, Müdigkeit","Kopfschmerzen, Nervosität","Durchfall, Bauchschmerzen","Vermehrtes Schwitzen"],"unbekannt":["Atemdepression (abgeschwächte Atmung), v. a. bei hohen Dosen","Verstopfung","Verwirrtheit, Halluzinationen, Euphorie","Abhängigkeit und Entzugssymptome","Überempfindlichkeitsreaktionen"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit. Längere Anwendung kann beim Neugeborenen Entzugssymptome, Anwendung unter der Geburt eine Atemdepression auslösen.","stillzeit":"Nicht stillen, da die Wirkstoffe in die Muttermilch übergehen können.","hinweise":["Retardtabletten ganz schlucken, nicht zerkauen oder zerkleinern.","Kein Alkohol; die Fahrtüchtigkeit ist vor allem zu Beginn und bei Dosisänderungen eingeschränkt.","Nach längerer Anwendung nicht abrupt absetzen (Entzugssymptome)."],"darreichung":["Retardtabletten","Tropfen (Lösung zum Einnehmen)"]},"timolol":{"wirkmechanismus":"Senkt den Augeninnendruck, indem weniger Kammerwasser gebildet wird. Timolol ist ein nicht selektiver Betablocker ohne eigene sympathomimetische Aktivität; es blockiert Beta-1- und Beta-2-Rezeptoren im Ziliarkörper und drosselt so die Kammerwasserproduktion. Auch als Augentropfen gelangt ein Teil über die Nasen- und Rachenschleimhaut in den Kreislauf und kann Puls, Blutdruck und Bronchien beeinflussen. Abgebaut wird Timolol hauptsächlich über das Leberenzym CYP2D6.","nebenwirkungen":{"unbekannt":["Augenreizung (Brennen, Stechen, Rötung), trockenes Auge, verminderte Hornhautempfindlichkeit","Sehstörungen, Doppelbilder, hängendes Augenlid; Aderhautabhebung nach Glaukomoperation","Langsamer Puls (Bradykardie), Herzrhythmusstörungen, AV-Block, Herzinsuffizienz","Tiefer Blutdruck, kalte Hände und Füsse, Raynaud-Syndrom","Bronchospasmus (v. a. bei Asthma), Atemnot","Müdigkeit, Schwindel, Kopfschmerzen, Depression, Schlafstörungen","Verdeckte Unterzuckerung, Verstärkung einer Myasthenia gravis","Allergische Reaktionen bis Anaphylaxie, Hautausschlag, Verschlechterung einer Psoriasis"]},"schwangerschaft":"Nur anwenden, wenn es ärztlich klar notwendig ist. Bei Anwendung bis zur Geburt das Neugeborene in den ersten Lebenstagen auf langsamen Puls, Unterzuckerung und Atemprobleme überwachen.","stillzeit":"Timolol geht in die Muttermilch über; bei Augentropfen in üblicher Dosierung sind Wirkungen beim Säugling unwahrscheinlich. Nur nach ärztlicher Abwägung.","hinweise":["Nach dem Eintropfen das Auge 1–2 Minuten schliessen und den inneren Augenwinkel sanft zudrücken – so gelangt weniger Wirkstoff ins Blut.","Bei Asthma, Herzkrankheiten oder vor einer Operation die Anwendung der Augentropfen ärztlich angeben.","Bei mehreren Augenmitteln mindestens 5–10 Minuten Abstand einhalten; Augengel zuletzt anwenden."],"darreichung":["Augentropfen","Augengel"]},"tiotropium":{"wirkmechanismus":"Hält die Bronchien den ganzen Tag weiter offen. Tiotropium blockiert die Muskarinrezeptoren (v. a. M3) der Bronchialmuskulatur und verhindert so, dass der Nervenbotenstoff Acetylcholin die Bronchien verengt. Weil es sich nur sehr langsam vom M3-Rezeptor löst, hält die Wirkung über 24 Stunden an. Als quaternäre Ammoniumverbindung wird es kaum aus dem Darm aufgenommen und wirkt vor allem in der Lunge.","nebenwirkungen":{"haeufig":["Mundtrockenheit (meist leicht)"],"gelegentlich":["Schwindel, Kopfschmerzen, Geschmacksstörungen","Verschwommensehen","Vorhofflimmern","Rachenentzündung, Heiserkeit (Dysphonie), Husten","Sodbrennen (Reflux), Verstopfung, Mundsoor","Hautausschlag","Harnverhalt, Schmerzen beim Wasserlösen"],"selten":["Schlaflosigkeit","Glaukom, erhöhter Augeninnendruck","Herzrasen (Tachykardie), Herzklopfen, supraventrikuläre Tachykardie","Bronchospasmus, Nasenbluten, Kehlkopf- und Nasennebenhöhlenentzündung","Darmverschluss einschliesslich Darmlähmung (paralytischer Ileus), Schluckbeschwerden, Übelkeit, Zahnfleisch- und Mundschleimhautentzündung","Überempfindlichkeitsreaktionen: Nesselsucht, Juckreiz, Angioödem","Harnwegsinfekte"],"unbekannt":["Anaphylaxie (schwere allergische Reaktion)","Dehydratation (Flüssigkeitsmangel)","Zahnkaries","Trockene Haut, Hautinfektionen und Hautgeschwüre","Gelenkschwellung"]},"schwangerschaft":"Sehr begrenzte Erfahrungen; vorsichtshalber nicht anwenden, ausser der Nutzen überwiegt klar.","stillzeit":"Nicht bekannt, ob Tiotropium beim Menschen in die Muttermilch übergeht; Anwendung nur nach ärztlicher Abwägung.","hinweise":["Einmal täglich zur gleichen Zeit inhalieren; nicht zur Behandlung akuter Atemnot.","HandiHaler-Kapseln nur inhalieren, nie schlucken.","Pulver und Sprühnebel nicht in die Augen bringen; bei Augenschmerzen, verschwommenem Sehen, Farbringen um Lichter oder geröteten Augen sofort ärztliche Hilfe holen (Glaukomanfall).","Gute Mundhygiene und regelmässige Zahnkontrollen, da Mundtrockenheit Karies fördern kann."],"darreichung":["Kapseln mit Pulver zur Inhalation (HandiHaler)","Lösung zur Inhalation (Respimat-Inhalator)"]},"tiotropium-olodaterol":{"wirkmechanismus":"Hält die Bronchien bei COPD rund um die Uhr weiter offen. Tiotropium blockiert langanhaltend die Muskarinrezeptoren (v. a. M3) der Bronchialmuskulatur und hemmt die verengende Wirkung von Acetylcholin. Olodaterol stimuliert als langwirksames Beta-2-Sympathomimetikum die Beta-2-Rezeptoren und entspannt die Bronchialmuskulatur. Beide Wirkungen halten 24 Stunden an.","nebenwirkungen":{"gelegentlich":["Schwindel, Kopfschmerzen","Herzrasen (Tachykardie)","Husten, Heiserkeit (Dysphonie)","Mundtrockenheit"],"selten":["Vorhofflimmern, Herzklopfen, supraventrikuläre Tachykardie","Bluthochdruck","Schlaflosigkeit, verschwommenes Sehen","Kehlkopf- und Rachenentzündung, Nasenbluten, Bronchospasmus","Verstopfung, Übelkeit, Mundsoor, Zahnfleisch- und Mundschleimhautentzündung","Überempfindlichkeitsreaktionen: Ausschlag, Juckreiz, Nesselsucht, Angioödem","Harnverhalt, Harnwegsinfekte, Schmerzen beim Wasserlösen","Rücken- und Gelenkschmerzen"],"unbekannt":["Glaukom, erhöhter Augeninnendruck","Darmverschluss einschliesslich Darmlähmung (paralytischer Ileus), Schluckbeschwerden, Reflux","Dehydratation (Flüssigkeitsmangel)","Zahnkaries","Nasennebenhöhlenentzündung"]},"schwangerschaft":"Sehr begrenzte Erfahrungen; vorsichtshalber nicht anwenden, ausser der Nutzen überwiegt klar. Olodaterol kann die Wehentätigkeit hemmen.","stillzeit":"Nicht bekannt, ob die Wirkstoffe beim Menschen in die Muttermilch übergehen (im Tierversuch ja); Anwendung nur nach ärztlicher Abwägung.","hinweise":["Einmal täglich zur gleichen Zeit inhalieren; nicht zur Behandlung akuter Atemnot.","Den Respimat vor dem ersten Gebrauch richtig vorbereiten (Patrone einsetzen, Testhübe) und den Sprühnebel nicht in die Augen bringen.","Bei Augenschmerzen, verschwommenem Sehen, Farbringen um Lichter oder geröteten Augen sofort ärztliche Hilfe holen (Glaukomanfall)."],"darreichung":["Lösung zur Inhalation (Respimat-Inhalator)"]},"tirofiban":{"wirkmechanismus":"Verhindert, dass Blutplättchen miteinander verkleben und ein Gerinnsel bilden. Tirofiban ist ein nicht-peptidischer, reversibler Hemmstoff des Glykoprotein-IIb/IIIa-Rezeptors, über den Fibrinogen die Blutplättchen vernetzt. Dadurch wird der gemeinsame Endweg der Plättchenaggregation blockiert. Nach Ende der Infusion erholt sich die Plättchenfunktion innerhalb weniger Stunden; ausgeschieden wird es vor allem über die Niere.","nebenwirkungen":{"sehrHaeufig":["Blutungen, v. a. an der Punktionsstelle und nach Eingriffen"],"haeufig":["Übelkeit","Kopfschmerzen","Fieber","Blutergüsse (Hämatome)","Blutungen aus Zahnfleisch, Magen-Darm-Trakt oder Harnwegen"],"unbekannt":["Hirnblutung, Blutung im Wirbelkanal","Blutung in den Bauchraum (retroperitoneal) oder in die Lunge","Blutung in den Herzbeutel (Hämoperikard)","Akuter schwerer Abfall der Blutplättchen","Anaphylaxie (schwere allergische Reaktion)"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; nur anwenden, wenn klar notwendig.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Wird nur im Spital als Infusion gegeben, in der Regel zusammen mit ASS und Heparin.","Thrombozyten, Hämoglobin und Gerinnungswerte werden vor und während der Behandlung kontrolliert.","Blutungen, schwarzen Stuhl, Blut im Urin oder plötzliche starke Kopfschmerzen sofort melden."],"darreichung":["Infusionslösung","Konzentrat zur Herstellung einer Infusionslösung"]},"tirzepatid":{"wirkmechanismus":"Senkt Blutzucker und Körpergewicht, indem es die Wirkung zweier körpereigener Darmhormone nachahmt. Tirzepatid ist ein einmal wöchentlich gespritzter Agonist an den Rezeptoren für GIP (glukoseabhängiges insulinotropes Polypeptid) und GLP-1 (Glucagon-like Peptide-1). Es steigert blutzuckerabhängig die Insulinausschüttung, senkt den Glukagonspiegel, verzögert die Magenentleerung und vermindert über Signale im Gehirn Hunger und Nahrungsaufnahme. Weil die Insulinfreisetzung vom Blutzucker abhängt, ist das Unterzuckerungsrisiko ohne Insulin oder Sulfonylharnstoffe gering.","nebenwirkungen":{"sehrHaeufig":["Übelkeit","Durchfall","Erbrechen und Verstopfung (bei Behandlung des Übergewichts sehr häufig, bei Typ-2-Diabetes häufig)","Hypoglykämie (Unterzuckerung) bei Kombination mit Insulin oder Sulfonylharnstoffen"],"haeufig":["Verminderter Appetit","Bauchschmerzen, Verdauungsbeschwerden (Dyspepsie), Blähungen, Aufstossen, Sodbrennen (Reflux)","Müdigkeit (Fatigue), Schwindel","Reaktionen an der Einstichstelle (Rötung, Juckreiz)","Haarausfall (vor allem bei Gewichtsbehandlung)","Erhöhter Puls, tiefer Blutdruck","Anstieg der Bauchspeicheldrüsen-Enzyme (Lipase, Amylase) im Blut","Überempfindlichkeitsreaktionen"],"gelegentlich":["Gallensteine (Cholelithiasis), Gallenblasenentzündung (Cholezystitis)","Akute Pankreatitis (Bauchspeicheldrüsenentzündung)","Geschmacksstörung","Anstieg des Calcitonins im Blut"],"unbekannt":["Anaphylaxie und Angioödem (schwere allergische Reaktionen)","Aspiration von Mageninhalt bei Narkose oder tiefer Sedierung"]},"schwangerschaft":"Nicht anwenden. Frauen im gebärfähigen Alter sollen sicher verhüten (siehe Pille); bei Kinderwunsch Tirzepatid wegen der langen Wirkdauer mindestens 1 Monat vor einer geplanten Schwangerschaft absetzen.","stillzeit":"Nicht empfohlen, da unbekannt ist, ob Tirzepatid in die Muttermilch übergeht; Entscheid nach ärztlicher Abwägung.","hinweise":["Einmal wöchentlich am gleichen Wochentag unter die Haut von Bauch, Oberschenkel oder Oberarm spritzen, unabhängig von den Mahlzeiten; Einstichstelle wechseln.","Eine vergessene Dosis innerhalb von 4 Tagen nachholen, sonst auslassen und zum gewohnten Termin weiterfahren.","Kleinere Mahlzeiten, langsames Essen und ausreichendes Trinken mildern Magen-Darm-Beschwerden; bei anhaltenden starken Bauchschmerzen sofort ärztlich abklären (Pankreatitis).","Vor Operationen, Narkosen und Magen-Darm-Spiegelungen die Behandlung angeben."],"darreichung":["Injektionslösung im Fertigpen (zur Injektion unter die Haut)"]},"tizanidin":{"wirkmechanismus":"Entspannt verkrampfte Muskeln, indem es überaktive Nervenreflexe im Rückenmark dämpft. Tizanidin stimuliert zentrale Alpha-2-Adrenozeptoren und vermindert so die Freisetzung erregender Aminosäuren aus Zwischennervenzellen des Rückenmarks; dadurch werden polysynaptische Reflexe gehemmt. Als Alpha-2-Agonist senkt es zudem Blutdruck und Puls und wirkt beruhigend. Es wird fast vollständig über CYP1A2 in der Leber abgebaut.","nebenwirkungen":{"sehrHaeufig":["Schläfrigkeit, Müdigkeit (v. a. bei höheren Dosen gegen Spastik)","Schwindel","Mundtrockenheit"],"haeufig":["Blutdruckabfall","Übelkeit, Magen-Darm-Beschwerden","Muskelschwäche","Erhöhte Leberwerte (Transaminasen)"],"gelegentlich":["Langsamer Puls (Bradykardie)"],"selten":["Halluzinationen","Schlaflosigkeit, Schlafstörungen"],"sehrSelten":["Hepatitis, Leberversagen"],"unbekannt":["Entzugserscheinungen nach abruptem Absetzen: Blutdruckanstieg, Herzrasen (Rebound)","Verwirrtheit","Verschwommenes Sehen","Hautausschlag, Juckreiz","Ohnmacht"]},"schwangerschaft":"Nicht empfohlen; nur wenn unbedingt nötig, nach ärztlicher Abwägung.","stillzeit":"Nicht anwenden, da Tizanidin in die Muttermilch übergehen kann.","hinweise":["Nicht abrupt absetzen, sondern langsam ausschleichen – sonst Blutdruckanstieg und Herzrasen möglich.","Alkohol meiden; Schläfrigkeit, Schwindel und Blutdruckabfall beeinträchtigen die Fahrtüchtigkeit – langsam aufstehen.","Bei höheren Dosen in den ersten Monaten Leberwerte kontrollieren.","Neu verordnete Medikamente, vor allem Antibiotika und Antidepressiva, immer auf Wechselwirkungen prüfen lassen."],"darreichung":["Tabletten"]},"tobramycin":{"wirkmechanismus":"Tötet Bakterien ab, indem es ihre Eiweissherstellung stört. Tobramycin bindet an die 30S-Untereinheit der bakteriellen Ribosomen und führt zu Ablesefehlern; die entstehenden fehlerhaften Eiweisse schädigen die Bakterienmembran. Die Wirkung ist konzentrationsabhängig und hält nach (postantibiotischer Effekt); besonders wirksam ist es gegen gramnegative Erreger einschliesslich Pseudomonas aeruginosa. Aus dem Darm wird es nicht aufgenommen; beim Inhalieren entstehen hohe Spiegel im Bronchialschleim bei geringer Aufnahme ins Blut.","nebenwirkungen":{"sehrHaeufig":["Bei Inhalationspulver: Husten, Heiserkeit, Atemnot, Halsschmerzen, Bluthusten, Fieber"],"haeufig":["Bei Inhalation: Tinnitus (Ohrensausen) und Hörminderung","Bei Inhalation: Bronchospasmus (Verkrampfung der Atemwege), pfeifende Atmung","Geschmacksstörungen, Übelkeit, Erbrechen","Nasenbluten, Hautausschlag","Bei Augentropfen: Augenbeschwerden und Augenrötung"],"gelegentlich":["Bei Augentropfen: Lidschwellung und -rötung, Juckreiz, Tränenfluss, Hornhautentzündung, verschwommenes Sehen"],"selten":["Schwindel, Kopfschmerzen, Stimmverlust"],"sehrSelten":["Pilzinfektionen im Mund","Überempfindlichkeitsreaktionen, Nesselsucht"],"unbekannt":["Bei Infusion: Nierenschädigung (Anstieg von Kreatinin und Harnstoff)","Bei Infusion: bleibende Innenohrschäden mit Hörverlust und Gleichgewichtsstörungen","Neuromuskuläre Blockade bis zur Atemlähmung","Elektrolytstörungen (Magnesium-, Calcium- und Kaliummangel)","Blutbildveränderungen (Anämie, Leukopenie, Thrombozytopenie)","Anaphylaxie (schwere allergische Reaktion)","Clostridioides-difficile-Kolitis"]},"schwangerschaft":"Aminoglykoside gehen über die Plazenta und können beim Kind bleibende Innenohrschäden (Taubheit) verursachen: Infusion und Inhalation nur bei zwingender Indikation. Augentropfen und -salbe nach ärztlicher Abwägung vertretbar.","stillzeit":"Geht in geringen Mengen in die Muttermilch über und wird vom Säugling kaum aufgenommen. Nach ärztlicher Abwägung möglich; Kind auf Durchfall und Pilzbefall beobachten.","hinweise":["Inhalation: zuerst den bronchienerweiternden Spray und die Atemphysiotherapie, Tobramycin zuletzt; nicht mit anderen Mitteln im Vernebler mischen.","Hörminderung, Ohrensausen oder Schwindel sofort ärztlich melden.","Bei Infusion werden Blutspiegel, Nierenwerte und bei längerer Therapie das Gehör kontrolliert.","Augentropfen: während der Infektion keine Kontaktlinsen tragen."],"darreichung":["Lösung für einen Vernebler","Inhalationspulver in Hartkapseln","Augentropfen","Augensalbe","Injektions- und Infusionslösung"]},"tobramycin-dexamethason":{"wirkmechanismus":"Hemmt die Entzündung und bekämpft gleichzeitig Bakterien am Auge. Dexamethason ist ein stark wirksames Glukokortikoid, das die Bildung entzündungsfördernder Botenstoffe unterdrückt und Rötung, Schwellung und Schmerzen lindert. Tobramycin ist ein Aminoglykosid-Antibiotikum, das an die bakteriellen Ribosomen bindet und die Eiweisssynthese stört. Es wirkt bakterizid, besonders gegen Staphylokokken und gramnegative Keime wie Pseudomonas aeruginosa.","nebenwirkungen":{"gelegentlich":["Erhöhter Augeninnendruck","Augenschmerzen, Augenjucken, Augenreizung und Augenbeschwerden"],"selten":["Keratitis (Hornhautentzündung)","Allergische Reaktion am Auge","Verschwommenes Sehen, trockenes Auge, Augenrötung","Geschmacksstörung"],"unbekannt":["Überempfindlichkeitsreaktionen, Gesichtsschwellung, Erythema multiforme","Schwindel, Kopfschmerzen","Lidschwellung, Pupillenerweiterung, vermehrter Tränenfluss","Übelkeit, Bauchbeschwerden","Glaukom, Linsentrübung (Katarakt) und Hornhautverdünnung bei längerer Anwendung","Pilz- oder Virusinfektionen des Auges (Sekundärinfektion)"]},"schwangerschaft":"Keine ausreichenden Daten; Aminoglykoside können bei systemischer Gabe das Gehör des Ungeborenen schädigen. Nur bei klarer Notwendigkeit und kurzzeitig anwenden.","stillzeit":"Nicht bekannt, ob die Wirkstoffe nach Anwendung am Auge in die Muttermilch gelangen; nur nach ärztlicher Abwägung.","hinweise":["Augentropfen vor Gebrauch gut schütteln.","Nicht länger als ärztlich verordnet anwenden; bei längerer Anwendung den Augeninnendruck kontrollieren lassen.","Während der Behandlung keine Kontaktlinsen tragen."],"darreichung":["Augentropfen (Suspension)","Augensalbe"]},"tocilizumab":{"wirkmechanismus":"Dämpft Entzündungen, indem es die Wirkung des Botenstoffs Interleukin-6 blockiert. Tocilizumab ist ein humanisierter monoklonaler IgG1-Antikörper, der an lösliche und membrangebundene IL-6-Rezeptoren bindet und so die IL-6-Signalübertragung hemmt. Dadurch sinken Entzündung, Fieber und Akutphase-Eiweisse wie das CRP. Weil IL-6 die Leberenzyme des Arzneimittelabbaus (Cytochrom P450) unterdrückt, normalisiert sich deren Aktivität unter Tocilizumab wieder.","nebenwirkungen":{"sehrHaeufig":["Infektionen der oberen Atemwege","Erhöhtes Cholesterin"],"haeufig":["Zellulitis (Hautinfektion), Lungenentzündung, Herpes simplex und Gürtelrose","Neutropenie, Leukopenie","Erhöhte Leberwerte und Bilirubin","Kopfschmerzen, Schwindel","Bluthochdruck","Bauchschmerzen, Mundgeschwüre, Gastritis","Ausschlag, Juckreiz, Nesselsucht","Infusions- oder Injektionsreaktionen, periphere Ödeme, Gewichtszunahme"],"gelegentlich":["Divertikulitis","Magengeschwür, Stomatitis (Mundschleimhautentzündung)","Erhöhte Triglyceride","Nierensteine","Schilddrüsenunterfunktion"],"selten":["Stevens-Johnson-Syndrom","Medikamentenbedingte Leberschädigung, Hepatitis, Gelbsucht"],"sehrSelten":["Leberversagen"],"unbekannt":["Anaphylaxie (schwere, auch tödliche allergische Reaktion)","Magen-Darm-Durchbruch (Perforation), meist als Komplikation einer Divertikulitis"]},"schwangerschaft":"Nur bei klarer Notwendigkeit nach ärztlicher Abwägung; Frauen im gebärfähigen Alter verhüten während und bis 3 Monate nach der Behandlung.","stillzeit":"Übergang in die Muttermilch ist unbekannt; Entscheid über Stillen oder Therapie ärztlich abwägen.","hinweise":["Weil Fieber und CRP unterdrückt werden, bei jedem Krankheitsgefühl, Husten oder Bauchschmerzen früh ärztlich abklären lassen.","Leberwerte, Blutbild und Blutfette werden regelmässig kontrolliert.","Vor Beginn auf Tuberkulose testen und Impfungen auffrischen.","Fertigspritzen im Kühlschrank lagern, nicht einfrieren."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung","Injektionslösung (Fertigspritze, Fertigpen)"]},"tocopherol-vitamin-e":{"wirkmechanismus":"Schützt die Zellmembranen vor Schäden durch aggressive Sauerstoffverbindungen (freie Radikale). Alpha-Tocopherol ist das wichtigste fettlösliche Antioxidans des Körpers: Es fängt Radikale ab und verhindert so die Oxidation mehrfach ungesättigter Fettsäuren in Zellmembranen und Lipoproteinen. Ein Mangel tritt fast nur bei gestörter Fettaufnahme auf und kann Nerven- und Muskelschäden sowie eine Blutarmut durch Zerfall roter Blutkörperchen verursachen.","nebenwirkungen":{"unbekannt":["Magen-Darm-Beschwerden (Übelkeit, Durchfall, Bauchkrämpfe) bei hohen Dosen","Müdigkeit, Kopfschmerzen","Überempfindlichkeitsreaktionen der Haut","Erhöhte Blutungsneigung bei sehr hohen Dosen, besonders bei Vitamin-K-Mangel"]},"schwangerschaft":"Dosen im Bereich des Tagesbedarfs sind unbedenklich; höhere Dosen nur nach ärztlicher Abwägung.","stillzeit":"Vitamin E geht in die Muttermilch über; übliche Dosen sind unbedenklich, höhere nur nach ärztlicher Abwägung.","hinweise":["Zu einer Mahlzeit einnehmen – Vitamin E wird zusammen mit Fett besser aufgenommen.","Vor Operationen die Einnahme hoher Vitamin-E-Dosen angeben.","Hoch dosiertes Vitamin E ist nur bei einem nachgewiesenen Mangel sinnvoll."],"darreichung":["Kapseln"]},"tofacitinib":{"wirkmechanismus":"Dämpft Entzündungen, indem es die Signalweiterleitung vieler Entzündungsbotenstoffe in den Immunzellen unterbricht. Tofacitinib hemmt bevorzugt die Enzyme Januskinase 1 und 3 (JAK1/JAK3), die Signale von Zytokin-Rezeptoren über STAT-Eiweisse an den Zellkern weitergeben. Dadurch werden Aktivierung und Vermehrung von Lymphozyten sowie die Bildung entzündungsfördernder Botenstoffe gehemmt.","nebenwirkungen":{"haeufig":["Lungenentzündung, Grippe, Gürtelrose, Harnwegsinfekte, Nasennebenhöhlen- und Rachenentzündung, Bronchitis","Anämie (Blutarmut), Lymphopenie","Kopfschmerzen","Bluthochdruck","Husten","Bauchschmerzen, Erbrechen, Durchfall, Übelkeit, Gastritis","Hautausschlag, Akne","Gelenkschmerzen, Ödeme, Fieber, Müdigkeit, erhöhte Kreatinkinase"],"gelegentlich":["Tuberkulose, Divertikulitis, Nierenbeckenentzündung, Zellulitis","Nicht-melanozytärer Hautkrebs, Lungenkrebs","Leukopenie, Neutropenie","Erhöhte Blutfette, Fettleber, erhöhte Leberwerte","Herzinfarkt","Tiefe Venenthrombose, Lungenembolie","Schlaflosigkeit, Parästhesien (Kribbeln)","Sehnenentzündung, Gelenkschwellung"],"selten":["Sepsis","Opportunistische Infektionen (z. B. Pneumocystis-Pneumonie, Zytomegalie)"],"sehrSelten":["Tuberkulose des Nervensystems, Kryptokokken-Meningitis"],"unbekannt":["Lymphome","Überempfindlichkeitsreaktionen (Angioödem, Nesselsucht)","Magen-Darm-Durchbruch (Perforation)"]},"schwangerschaft":"Kontraindiziert. Frauen im gebärfähigen Alter verhüten während und bis mindestens 4 Wochen nach der letzten Dosis zuverlässig.","stillzeit":"Kontraindiziert; nicht stillen.","hinweise":["Vor Beginn auf Tuberkulose und Hepatitis testen und Impfungen (inkl. Gürtelrose) aktualisieren lassen.","Bei plötzlicher Atemnot, Brustschmerz oder geschwollenem, schmerzhaftem Bein sofort ärztliche Hilfe holen (Thrombose, Lungenembolie).","Blutbild, Leberwerte und Blutfette werden regelmässig kontrolliert; regelmässige Hautkontrollen.","Kein Grapefruitsaft in grösseren Mengen; Retardtabletten nicht teilen oder zerkauen."],"darreichung":["Filmtabletten","Retardtabletten"]},"tolterodin":{"wirkmechanismus":"Beruhigt die überaktive Blase, sodass sie mehr Urin speichern kann und der Harndrang nachlässt. Tolterodin ist ein kompetitiver Muskarinrezeptor-Antagonist, der im Körper stärker an der Blase als an den Speicheldrüsen wirkt. Es wird über CYP2D6 zum gleich stark wirksamen 5-Hydroxymethyl-Metaboliten (5-HMT) umgewandelt; bei Menschen mit wenig CYP2D6-Aktivität (langsame Metabolisierer) erfolgt der Abbau über CYP3A4, und der Tolterodin-Spiegel ist höher.","nebenwirkungen":{"sehrHaeufig":["Mundtrockenheit","Kopfschmerzen"],"haeufig":["Bronchitis","Schwindel, Schläfrigkeit, Kribbeln (Parästhesien)","Trockene Augen, Sehstörungen (Akkommodationsstörungen)","Drehschwindel","Herzklopfen","Verdauungsbeschwerden, Verstopfung, Bauchschmerzen, Blähungen, Erbrechen, Durchfall","Schmerzen beim Wasserlassen, Harnverhalt","Müdigkeit, Brustschmerzen, Wassereinlagerungen in den Beinen, Gewichtszunahme"],"gelegentlich":["Überempfindlichkeitsreaktionen","Nervosität","Gedächtnisstörungen","Herzrasen, Herzrhythmusstörungen, Herzinsuffizienz","Reflux (saures Aufstossen)"],"unbekannt":["Anaphylaktoide Reaktionen, Angioödem","Verwirrtheit, Halluzinationen, Desorientierung","Verschlechterung von Demenzsymptomen","Gesichtsrötung (Flush)","Trockene Haut"]},"schwangerschaft":"Nicht empfohlen – es liegen keine ausreichenden Daten vor; im Tierversuch zeigte sich Reproduktionstoxizität.","stillzeit":"Vermeiden – es ist nicht bekannt, ob Tolterodin in die Muttermilch übergeht.","hinweise":["Retardkapseln ganz schlucken, nicht zerkauen; Einnahme unabhängig von den Mahlzeiten.","Kann Sehstörungen, Schwindel und Müdigkeit verursachen: Vorsicht beim Autofahren.","Wirkung nach 2–3 Monaten ärztlich überprüfen lassen."],"darreichung":["Filmtabletten","Retardkapseln"]},"tolvaptan":{"wirkmechanismus":"Lässt die Niere mehr Wasser ohne Salz ausscheiden. Tolvaptan blockiert selektiv den Vasopressin-V2-Rezeptor im Sammelrohr der Niere; dadurch werden weniger Wasserkanäle (Aquaporin-2) eingebaut und mehr freies Wasser ausgeschieden (Aquarese), während die Ausscheidung von Natrium und Kalium kaum zunimmt. So steigt der Natriumspiegel im Blut. Bei Zystennieren senkt die Blockade den zellulären cAMP-Spiegel, der das Wachstum der Zysten antreibt.","nebenwirkungen":{"sehrHaeufig":["Starker Durst","Vermehrtes und nächtliches Wasserlassen (Polyurie, Nykturie)","Mundtrockenheit","Übelkeit (bei Hyponatriämie-Behandlung)","Kopfschmerzen, Schwindel, Müdigkeit und Durchfall (bei Zystennieren-Behandlung)"],"haeufig":["Erhöhte Leberwerte","Hypernatriämie (zu hohes Natrium) und Flüssigkeitsmangel","Hyperkaliämie (erhöhtes Kalium)","Hyperglykämie (erhöhter Blutzucker), Appetitlosigkeit","Orthostatische Hypotonie (Blutdruckabfall beim Aufstehen), Herzklopfen","Verstopfung, Bauchschmerzen, Verdauungsbeschwerden","Hautausschlag, Juckreiz","Gewichtsabnahme, Schlaflosigkeit"],"gelegentlich":["Geschmacksstörungen","Anstieg des Bilirubins","Nierenfunktionsstörung (Kreatininanstieg)"],"unbekannt":["Akutes Leberversagen","Anaphylaxie (schwere allergische Reaktion)","Osmotisches Demyelinisierungssyndrom (Nervenschädigung) bei zu rascher Natriumkorrektur"]},"schwangerschaft":"Kontraindiziert; im Tierversuch fruchtschädigend. Frauen im gebärfähigen Alter müssen während der Behandlung zuverlässig verhüten.","stillzeit":"Kontraindiziert; während der Behandlung nicht stillen.","hinweise":["Die Behandlung einer Hyponatriämie wird im Spital begonnen; der Natriumspiegel wird in den ersten Tagen engmaschig kontrolliert.","Bei Jinarc vor Beginn und während der Behandlung regelmässig (anfangs monatlich) die Leberwerte kontrollieren; bei Müdigkeit, Appetitlosigkeit, Oberbauchschmerzen, dunklem Urin oder Gelbsucht sofort ärztlich melden.","Immer Wasser griffbereit haben und bei Durst trinken; keinen Grapefruitsaft trinken."],"darreichung":["Tabletten"]},"topiramat":{"wirkmechanismus":"Dämpft überaktive Nervenzellen auf mehreren Wegen und verhindert so Krampfanfälle und Migräneattacken. Topiramat blockiert spannungsabhängige Natriumkanäle, verstärkt die hemmende Wirkung von GABA am GABA-A-Rezeptor und hemmt erregende Glutamat-Rezeptoren vom AMPA/Kainat-Typ. Zusätzlich hemmt es schwach die Carboanhydrase, was Nierensteine und eine metabolische Azidose (Übersäuerung des Blutes) begünstigt.","nebenwirkungen":{"sehrHaeufig":["Schläfrigkeit, Schwindel","Kribbeln (Parästhesien)","Depression","Müdigkeit","Übelkeit, Durchfall","Gewichtsabnahme","Nasen-Rachen-Entzündung"],"haeufig":["Appetitverlust, Anämie","Verlangsamtes Denken, Wortfindungs-, Konzentrations- und Gedächtnisstörungen","Schlaflosigkeit, Angst, Verwirrtheit, Aggression","Geschmacksstörungen, Zittern, Sehstörungen (verschwommen, Doppelbilder)","Erbrechen, Verstopfung, Bauchschmerzen, Mundtrockenheit","Nierensteine, häufiges oder schmerzhaftes Wasserlassen","Haarausfall, Ausschlag, Juckreiz","Gelenkschmerzen, Muskelkrämpfe"],"gelegentlich":["Metabolische Azidose (Übersäuerung des Blutes), Hypokaliämie","Vermindertes Schwitzen (Oligohidrose), Überwärmung","Suizidgedanken, Psychose, Halluzinationen","Leukopenie, Thrombozytopenie"],"selten":["Hepatitis, Leberversagen","Stevens-Johnson-Syndrom, Erythema multiforme","Renale tubuläre Azidose"],"sehrSelten":["Toxische epidermale Nekrolyse"],"unbekannt":["Akute Kurzsichtigkeit mit sekundärem Engwinkelglaukom","Makulopathie, Sehfeldausfälle"]},"schwangerschaft":"Fruchtschädigend: erhöhtes Risiko für Fehlbildungen (z. B. Lippen-Kiefer-Gaumen-Spalten), Untergewicht und Entwicklungsstörungen. Zur Migräneprophylaxe kontraindiziert; bei Epilepsie nur, wenn keine Alternative besteht – nie eigenmächtig absetzen.","stillzeit":"Geht in die Muttermilch über; Stillen nur nach ärztlicher Abwägung, Kind auf Durchfall, Schläfrigkeit und schlechte Gewichtszunahme beobachten.","hinweise":["Frauen im gebärfähigen Alter benötigen eine hochwirksame Verhütung und vor Behandlungsbeginn einen Schwangerschaftstest.","Reichlich trinken, um Nierensteinen und Überwärmung vorzubeugen.","Bei plötzlichen Augenschmerzen oder Sehverschlechterung sofort ärztliche Hilfe holen.","Nicht abrupt absetzen – Gefahr von Krampfanfällen; Alkohol meiden."],"darreichung":["Filmtabletten"]},"torasemid":{"wirkmechanismus":"Fördert die Ausscheidung von Salz und Wasser über die Niere. Torasemid hemmt den Natrium-Kalium-2-Chlorid-Cotransporter im aufsteigenden Teil der Henle-Schleife und steigert so die Ausscheidung von Natrium, Chlorid und Wasser; der Kaliumverlust ist im Vergleich zu Furosemid etwas geringer. Die Wirkung hält mit 6–8 Stunden länger an als bei Furosemid, und der Wirkstoff wird aus dem Darm nahezu vollständig aufgenommen. In niedriger Dosis senkt es den Blutdruck vor allem über eine Abnahme des Gefässwiderstands. Torasemid wird überwiegend in der Leber (hauptsächlich über CYP2C9) abgebaut.","nebenwirkungen":{"haeufig":["Störungen des Wasser- und Elektrolythaushalts, z. B. Hypokaliämie (Kaliummangel), besonders bei kaliumarmer Ernährung, Erbrechen, Durchfall oder Leberzirrhose","Metabolische Alkalose, Muskelkrämpfe","Erhöhte Harnsäure, Blutzucker und Blutfette","Kopfschmerzen, Schwindel, Müdigkeit, Schwächegefühl","Magen-Darm-Beschwerden wie Appetitlosigkeit, Bauchschmerzen, Übelkeit, Erbrechen, Durchfall oder Verstopfung","Anstieg einzelner Leberwerte (z. B. Gamma-GT)"],"gelegentlich":["Mundtrockenheit","Kribbeln oder Taubheitsgefühl in Armen und Beinen (Parästhesien)","Harnverhalt bei Abflussstörungen (z. B. Prostatavergrösserung)","Anstieg von Kreatinin und Harnstoff im Blut"],"sehrSelten":["Thrombozytopenie, Leukopenie, Abnahme der roten Blutkörperchen","Pankreatitis (Bauchspeicheldrüsenentzündung)","Allergische Hautreaktionen (Juckreiz, Ausschlag), Lichtempfindlichkeit, schwere Hautreaktionen","Sehstörungen","Tinnitus (Ohrgeräusche) und Hörverlust","Thromboembolien, Durchblutungsstörungen von Herz und Gehirn und Blutdruckabfall durch Bluteindickung","Verwirrtheit"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit und in der niedrigsten wirksamen Dosis: Diuretika können die Durchblutung der Plazenta vermindern und beim Kind Elektrolytstörungen verursachen.","stillzeit":"Kontraindiziert; ist eine Behandlung nötig, muss abgestillt werden.","hinweise":["Am Morgen unzerkaut mit etwas Flüssigkeit einnehmen.","Körpergewicht bei Ödemen täglich kontrollieren; bei Durchfall, Erbrechen oder starkem Schwitzen ärztlichen Rat einholen.","Kalium, Natrium, Nierenwerte, Blutzucker und Harnsäure regelmässig kontrollieren lassen.","Kann besonders zu Beginn die Fahrtüchtigkeit beeinträchtigen, verstärkt durch Alkohol."],"darreichung":["Tabletten"]},"tralokinumab":{"wirkmechanismus":"Dämpft die allergische Entzündung der Haut und lindert dadurch Ekzeme und Juckreiz. Tralokinumab ist ein vollständig humaner IgG4-Antikörper, der spezifisch an das Zytokin Interleukin-13 (IL-13) bindet und dessen Andocken an die IL-13-Rezeptoren verhindert. IL-13 ist ein zentraler Botenstoff der sogenannten Typ-2-Entzündung bei Neurodermitis und schwächt unter anderem die Hautbarriere.","nebenwirkungen":{"sehrHaeufig":["Infektionen der oberen Atemwege (z. B. Erkältung)"],"haeufig":["Bindehautentzündung (Konjunktivitis), auch allergisch","Reaktionen an der Injektionsstelle (Rötung, Schwellung, Schmerzen)","Eosinophilie (Vermehrung bestimmter weisser Blutkörperchen)"],"gelegentlich":["Keratitis (Hornhautentzündung)"]},"schwangerschaft":"Nur begrenzte Erfahrungen; vorsichtshalber während der Schwangerschaft vermeiden.","stillzeit":"Nicht bekannt, ob Tralokinumab in die Muttermilch übergeht; Anwendung nur nach ärztlicher Abwägung.","hinweise":["Im Kühlschrank lagern; vor der Injektion etwa 30 Minuten auf Raumtemperatur kommen lassen.","Neu auftretende Augenrötung, Augenschmerzen oder Sehstörungen ärztlich abklären lassen.","Kortison- oder Calcineurinhemmer-Cremes können nach ärztlicher Anweisung weiter verwendet werden."],"darreichung":["Injektionslösung (Fertigspritze)","Injektionslösung (Fertigpen)"]},"tramadol":{"wirkmechanismus":"Lindert Schmerzen auf zwei Wegen: über die körpereigenen Opioid-Andockstellen und über eine Verstärkung der schmerzhemmenden Nervenbahnen. Tramadol wirkt schwach am μ-Opioidrezeptor, vor allem über sein Abbauprodukt O-Desmethyltramadol, das in der Leber durch CYP2D6 gebildet wird. Zusätzlich hemmt es die Wiederaufnahme von Noradrenalin und Serotonin im Rückenmark. Dadurch erklärt sich auch das Risiko für Serotonin-Syndrom und Krampfanfälle.","nebenwirkungen":{"sehrHaeufig":["Schwindel","Übelkeit"],"haeufig":["Kopfschmerzen, Schläfrigkeit","Erbrechen, Verstopfung, Mundtrockenheit","Starkes Schwitzen","Müdigkeit"],"gelegentlich":["Herzklopfen, Herzrasen, Kreislaufschwäche beim Aufstehen","Würgereiz, Magenbeschwerden, Durchfall","Juckreiz, Hautausschlag, Nesselsucht"],"selten":["Krampfanfälle","Halluzinationen, Verwirrtheit, Delir, Albträume","Abhängigkeit","Atemdepression, Atemnot","Allergische Reaktionen bis zur Anaphylaxie","Bradykardie (langsamer Puls), Blutdruckanstieg","Verschwommensehen, Pupillenveränderungen"],"sehrSelten":["Erhöhte Leberwerte"],"unbekannt":["Serotonin-Syndrom","Hypoglykämie (Unterzuckerung)","Hyponatriämie (Natriummangel)","Schluckauf"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung und nur kurzfristig; längere Anwendung kann beim Neugeborenen Entzugssymptome auslösen.","stillzeit":"Tramadol geht in die Muttermilch über. Nach einer einzelnen Dosis ist keine Stillpause nötig; bei wiederholter Einnahme wird vom Stillen abgeraten.","hinweise":["Retardtabletten ganz schlucken, nicht zerkauen oder zerkleinern.","Kein Alkohol; die Fahrtüchtigkeit kann vor allem zu Beginn eingeschränkt sein.","Nach längerer Anwendung nicht abrupt absetzen (Entzugssymptome).","Bei Diabetes auf Zeichen einer Unterzuckerung achten."],"darreichung":["Kapseln","Retardtabletten","Tropfen (Lösung zum Einnehmen)","Zäpfchen","Injektionslösung"]},"tramadol-paracetamol":{"wirkmechanismus":"Kombiniert zwei unterschiedlich wirkende Schmerzmittel, die sich ergänzen. Tramadol wirkt schwach an μ-Opioidrezeptoren – vor allem über sein durch CYP2D6 gebildetes Abbauprodukt O-Desmethyltramadol – und hemmt zusätzlich die Wiederaufnahme von Noradrenalin und Serotonin, was die körpereigene Schmerzhemmung im Rückenmark verstärkt. Paracetamol hemmt vor allem im Zentralnervensystem die Bildung von Prostaglandinen. Die Kombination wirkt rascher als Tramadol allein und länger als Paracetamol allein.","nebenwirkungen":{"sehrHaeufig":["Übelkeit","Schwindel","Schläfrigkeit"],"haeufig":["Kopfschmerzen, Zittern","Verwirrtheit, Stimmungsschwankungen, Schlafstörungen","Erbrechen, Verstopfung, Durchfall","Mundtrockenheit, Bauchschmerzen, Verdauungsbeschwerden","Schwitzen, Juckreiz"],"gelegentlich":["Depression, Halluzinationen, Albträume","Muskelzuckungen, Kribbeln, Ohrgeräusche","Herzrhythmusstörungen, Herzrasen, Bluthochdruck","Atemnot","Erhöhte Leberwerte","Hautausschlag, Nesselsucht"],"selten":["Krampfanfälle","Abhängigkeit, Delir","Ohnmacht, Koordinationsstörungen","Verschwommensehen"],"sehrSelten":["Missbrauch"],"unbekannt":["Serotonin-Syndrom","Hypoglykämie (Unterzuckerung)","Hyponatriämie (Natriummangel)","Atemdepression","Schwere Hautreaktionen","Anaphylaxie (schwere allergische Reaktion)"]},"schwangerschaft":"Soll in der Schwangerschaft nicht angewendet werden. Tramadol passiert die Plazenta; längere Anwendung kann beim Neugeborenen Entzugssymptome auslösen.","stillzeit":"Nicht empfohlen; Tramadol geht in die Muttermilch über. Nach einer einzelnen Einnahme ist eine Stillpause in der Regel nicht nötig.","hinweise":["Höchstens 8 Filmtabletten pro Tag (entspricht 2,6 g Paracetamol); keine weiteren paracetamol- oder tramadolhaltigen Mittel gleichzeitig.","Kein Alkohol; die Fahrtüchtigkeit kann eingeschränkt sein.","Nach längerer Anwendung nicht abrupt absetzen (Entzugssymptome).","Bei Diabetes auf Zeichen einer Unterzuckerung achten."],"darreichung":["Filmtabletten"]},"tranexamsaeure":{"wirkmechanismus":"Bremst den Abbau von Blutgerinnseln und hilft so, Blutungen zu stillen. Tranexamsäure ist ein synthetischer Abkömmling der Aminosäure Lysin. Es besetzt die Lysin-Bindungsstellen des Plasminogens und verhindert so, dass Plasminogen an Fibrin bindet und zu Plasmin aktiviert wird; in hohen Konzentrationen hemmt es auch Plasmin direkt. Dadurch bleibt das Fibringerinnsel länger stabil. Die Ausscheidung erfolgt überwiegend unverändert über die Nieren.","nebenwirkungen":{"haeufig":["Übelkeit, Erbrechen, Durchfall (dosisabhängig)"],"gelegentlich":["Allergische Hautentzündung"],"sehrSelten":["Überempfindlichkeitsreaktionen bis Anaphylaxie"],"unbekannt":["Thrombosen und Embolien (arteriell oder venös) an verschiedenen Stellen","Sehstörungen einschliesslich Farbsehstörungen, Verschluss von Netzhautgefässen","Krampfanfälle, besonders bei hohen intravenösen Dosen","Unwohlsein mit Blutdruckabfall, evtl. Bewusstlosigkeit bei zu rascher Injektion"]},"schwangerschaft":"Tranexamsäure passiert die Plazenta; bisherige Erfahrungen zeigen kein erhöhtes Fehlbildungsrisiko. Anwendung nur nach ärztlicher Abwägung, im ersten Drittel besonders zurückhaltend.","stillzeit":"Geht nur in geringen Mengen (etwa 1 % der Blutkonzentration) in die Muttermilch über; eine Wirkung beim Säugling ist unwahrscheinlich. Anwendung möglich.","hinweise":["Bei Sehstörungen sofort absetzen und augenärztlich abklären lassen.","Bei starker Monatsblutung nur während der Blutungstage einnehmen; bei unregelmässigen oder neu auftretenden Blutungen zuerst die Ursache abklären lassen.","Bei Anzeichen einer Thrombose (schmerzhafte Beinschwellung, Brustschmerz, Atemnot) sofort ärztliche Hilfe holen.","Die Injektion wird langsam intravenös gegeben; zu rasche Gabe kann einen Blutdruckabfall auslösen."],"darreichung":["Filmtabletten","Injektionslösung"]},"trastuzumab":{"wirkmechanismus":"Blockiert einen Wachstumsrezeptor, der auf manchen Krebszellen in grosser Zahl vorkommt. Trastuzumab ist ein humanisierter monoklonaler IgG1-Antikörper gegen den äusseren Teil des Rezeptors HER2 (ErbB2). Er hemmt die HER2-vermittelte Wachstumssignalisierung und markiert die Tumorzellen für die Zerstörung durch Immunzellen (antikörperabhängige zelluläre Zytotoxizität). Weil HER2 auch für die Erholung von Herzmuskelzellen wichtig ist, kann die Herzfunktion abnehmen.","nebenwirkungen":{"sehrHaeufig":["Infusionsreaktionen (Fieber, Schüttelfrost)","Infektionen, Nasen-Rachen-Entzündung","Neutropenie, febrile Neutropenie, Anämie, Thrombozytopenie (v. a. mit Chemotherapie)","Abnahme der Herzpumpfunktion, Herzklopfen, unregelmässiger Herzschlag","Kopfschmerzen, Schwindel, Kribbeln, Zittern, Geschmacksstörungen","Atemnot, Husten, Nasenbluten","Durchfall, Übelkeit, Erbrechen, Bauchschmerzen, Stomatitis","Hautausschlag, Haarausfall, Nagelveränderungen, Gelenk- und Muskelschmerzen, Müdigkeit"],"haeufig":["Herzschwäche (Herzinsuffizienz), Kardiomyopathie, supraventrikuläre Herzrhythmusstörungen","Blutdruckabfall","Pneumonitis, pfeifende Atmung","Leberzellschädigung","Überempfindlichkeitsreaktionen"],"gelegentlich":["Perikarderguss","Hörverlust"],"unbekannt":["Kardiogener Schock","Interstitielle Lungenerkrankung, Lungenfibrose, akutes Atemnotsyndrom","Anaphylaxie (schwere allergische Reaktion)","Oligohydramnion (zu wenig Fruchtwasser) bei Anwendung in der Schwangerschaft","Glomerulopathie, Nierenversagen"]},"schwangerschaft":"Nicht anwenden, ausser bei zwingender Indikation: Fälle von Oligohydramnion (zu wenig Fruchtwasser) mit schweren Folgen für das Kind. Frauen müssen während und bis 7 Monate nach der Behandlung sicher verhüten.","stillzeit":"Während der Behandlung und bis 7 Monate nach der letzten Gabe nicht stillen.","hinweise":["Herzultraschall vor Beginn und etwa alle 3 Monate; Atemnot, Herzklopfen oder geschwollene Beine melden.","Intravenöse und subkutane Form, Biosimilars und Trastuzumab-Konjugate (z. B. Trastuzumab-Emtansin, Trastuzumab-Deruxtecan) sind nicht austauschbar – Namen genau prüfen.","Sichere Verhütung bis 7 Monate nach der letzten Gabe."],"darreichung":["Pulver zur Herstellung eines Infusionslösungskonzentrats","Injektionslösung zur subkutanen Anwendung"]},"travoprost":{"wirkmechanismus":"Senkt den Augeninnendruck, indem mehr Kammerwasser aus dem Auge abfliesst. Travoprost ist ein Prodrug (Isopropylester), das in der Hornhaut zur aktiven freien Säure gespalten wird. Diese ist ein hochselektiver Agonist am Prostaglandin-FP-Rezeptor und steigert den uveoskleralen und den trabekulären Abfluss. Die Drucksenkung setzt nach etwa 2 Stunden ein und erreicht nach rund 12 Stunden ihr Maximum.","nebenwirkungen":{"sehrHaeufig":["Rötung des Auges (okuläre Hyperämie)"],"haeufig":["Dauerhaft dunklere Färbung der Iris (Regenbogenhaut)","Augenschmerzen, Augenbeschwerden, Augenreizung","Trockenes Auge","Juckreiz am Auge"],"gelegentlich":["Entzündungen im Auge (Uveitis, Iritis, Keratitis), Lichtempfindlichkeit","Verschwommenes Sehen, verminderte Sehschärfe","Wimpernwachstum, Lidrötung, Lidrandentzündung","Dunkelfärbung der Haut um das Auge, verstärkte Behaarung","Kopfschmerzen","Husten, verstopfte Nase"],"selten":["Herpes-simplex-Infektion des Auges","Schwindel, Geschmacksstörung","Herzklopfen, unregelmässiger oder verlangsamter Puls","Blutdruckveränderungen","Atemnot, Asthma","Allergische Hautreaktionen"],"unbekannt":["Makulaödem (Schwellung der Netzhautmitte)","Einsinken der Augen (Vertiefung der Lidfurche)","Verschlechterung eines Asthmas","Brustschmerzen, Herzrhythmusstörungen"]},"schwangerschaft":"Nur bei klarer Notwendigkeit anwenden, da Travoprost der Schwangerschaft und dem Ungeborenen schaden kann. Frauen im gebärfähigen Alter dürfen es nur mit zuverlässiger Verhütung anwenden.","stillzeit":"Nicht empfohlen: Travoprost geht im Tierversuch in die Milch über.","hinweise":["Einmal täglich (meist abends) eintropfen; nicht häufiger anwenden.","Nach dem Eintropfen die Augen 2 Minuten schliessen oder den inneren Augenwinkel zudrücken.","Kontaktlinsen frühestens 15 Minuten nach dem Eintropfen wieder einsetzen; zu anderen Augentropfen 5 Minuten Abstand halten."],"darreichung":["Augentropfen"]},"travoprost-timolol":{"wirkmechanismus":"Senkt den Augeninnendruck auf zwei Wegen: Es fördert den Abfluss des Kammerwassers und drosselt dessen Bildung. Travoprost ist ein Prodrug, das in der Hornhaut zur freien Säure gespalten wird; diese aktiviert den Prostaglandin-FP-Rezeptor und steigert vor allem den uveoskleralen Abfluss. Timolol blockiert nicht-selektiv die Beta-Rezeptoren im Ziliarkörper und vermindert so die Kammerwasserproduktion. Ein Teil des Timolols gelangt über die Nasenschleimhaut ins Blut und kann wie ein Betablocker in Tablettenform auf Herz und Bronchien wirken.","nebenwirkungen":{"sehrHaeufig":["Rötung des Auges (okuläre Hyperämie)"],"haeufig":["Punktförmige Hornhautentzündung (Keratitis punctata)","Augenschmerzen, Augenreizung, Juckreiz am Auge","Verschwommenes Sehen, Sehstörungen","Trockenes Auge"],"gelegentlich":["Bradykardie (verlangsamter Puls)","Blutdruckanstieg oder -abfall","Schwindel, Kopfschmerzen","Atemnot (Dyspnoe)","Entzündungen am Auge (Iritis, Konjunktivitis, Blepharitis), Lichtempfindlichkeit","Wimpernwachstum, verstärkte Behaarung und dunklere Haut um das Auge","Überempfindlichkeitsreaktionen"],"selten":["Bronchospasmus (Verkrampfung der Atemwege), Husten","Herzrhythmusstörungen","Hornhauterosion (oberflächlicher Hornhautschaden)","Erhöhte Leberwerte","Nesselsucht, Haarausfall"],"unbekannt":["Dauerhafte Braunfärbung der Iris (Regenbogenhaut)","Makulaödem (Schwellung der Netzhautmitte)","Asthma","Herzinsuffizienz, Herzklopfen, Brustschmerzen","Depression","Herabhängendes Oberlid (Ptosis)"]},"schwangerschaft":"Nur bei klarer Notwendigkeit anwenden: Travoprost hat im Tierversuch der Schwangerschaft geschadet, und Timolol kann bei Anwendung bis zur Geburt beim Neugeborenen Puls und Blutzucker senken. Frauen im gebärfähigen Alter sollen zuverlässig verhüten.","stillzeit":"Nicht empfohlen: beide Wirkstoffe gehen wahrscheinlich in die Muttermilch über; Timolol kann beim Säugling Herz und Atmung beeinträchtigen.","hinweise":["Nach dem Eintropfen die Augen 2 Minuten schliessen oder den inneren Augenwinkel leicht zudrücken – das vermindert die Aufnahme ins Blut und Nebenwirkungen an Herz und Lunge.","Kontaktlinsen vor dem Eintropfen herausnehmen und frühestens nach 15 Minuten wieder einsetzen; zu anderen Augentropfen mindestens 5 Minuten Abstand halten.","Überschüssige Tropfen von der Haut abwischen (Haarwuchs und Hautverfärbung möglich).","Unmittelbar nach dem Eintropfen kann die Sicht verschwommen sein – erst bei klarer Sicht Auto fahren."],"darreichung":["Augentropfen"]},"trazodon":{"wirkmechanismus":"Hellt die Stimmung auf, wirkt angstlösend und schlaffördernd. Trazodon blockiert vor allem Serotonin-5-HT2A-Rezeptoren und hemmt schwächer die Wiederaufnahme von Serotonin; zusätzlich blockiert es Alpha-1-Adrenozeptoren und Histamin-H1-Rezeptoren, was die beruhigende Wirkung und den möglichen Blutdruckabfall erklärt. Anticholinerge Wirkungen sind gering. Der Abbau erfolgt hauptsächlich über CYP3A4.","nebenwirkungen":{"unbekannt":["Schläfrigkeit, Müdigkeit, Schwindel, Kopfschmerzen","Mundtrockenheit, Übelkeit, Erbrechen","Blutdruckabfall beim Aufstehen (orthostatische Hypotonie), Ohnmacht","Herzrhythmusstörungen, QT-Verlängerung","Priapismus (schmerzhafte Dauererektion – Notfall)","Hyponatriämie (Natriummangel), Serotoninsyndrom, Krampfanfälle","Blutbildveränderungen (z. B. Agranulozytose, Thrombozytopenie), Leberfunktionsstörungen","Suizidgedanken und suizidales Verhalten"]},"schwangerschaft":"Begrenzte Erfahrungen; nur bei klarer Notwendigkeit nach ärztlicher Abwägung. Bei Einnahme bis zur Geburt das Neugeborene auf Absetzsymptome beobachten.","stillzeit":"Trazodon geht in geringen Mengen in die Muttermilch über; Anwendung nur nach ärztlicher Abwägung.","hinweise":["Nach einer Mahlzeit einnehmen, die Hauptdosis vorzugsweise abends (macht müde).","Bei einer anhaltenden, schmerzhaften Erektion sofort ärztliche Hilfe holen (Notfall).","Kann die Fahrtüchtigkeit beeinträchtigen; Alkohol meiden.","Langsam aufstehen (Schwindel durch Blutdruckabfall); nicht abrupt absetzen."],"darreichung":["Tabletten","Retardtabletten"]},"tretinoin":{"wirkmechanismus":"Normalisiert die Verhornung der Haut und löst Mitesser; bei Leukämie lässt es unreife Krebszellen ausreifen. Tretinoin (all-trans-Retinsäure) bindet an Retinsäure-Rezeptoren (RAR) im Zellkern und steuert Gene für Zellwachstum und Zellreifung. In der Haut beschleunigt es die Erneuerung der Oberhaut, lockert verhornte Talgdrüsenausgänge und beugt neuen Komedonen vor. Bei der akuten Promyelozytenleukämie überwindet es in hoher Konzentration die Blockade durch das Fusionsprotein PML-RARα, sodass die leukämischen Promyelozyten zu reifen Granulozyten ausdifferenzieren.","nebenwirkungen":{"sehrHaeufig":["Hautreizung an der Auftragsstelle mit Rötung, Schuppung, Brennen und Trockenheit (Creme)","Differenzierungssyndrom (Retinsäure-Syndrom) bei der Leukämiebehandlung: Fieber, Atemnot, Wassereinlagerungen","Kopfschmerzen, erhöhter Hirndruck (Pseudotumor cerebri), Schwindel","Trockene Haut und Schleimhäute, Lippenentzündung (Cheilitis), Ausschlag, Haarausfall (Kapseln)","Übelkeit, Erbrechen, Bauchschmerzen (Kapseln)","Erhöhte Blutfette (Triglyceride, Cholesterin) und Leberwerte (Kapseln)","Knochen- und Brustschmerzen, Fieber, Frösteln (Kapseln)","Seh- und Hörstörungen, Depression, Verwirrtheit (Kapseln)"],"unbekannt":["Thrombosen in Venen und Arterien (z. B. Herzinfarkt, Schlaganfall)","Starker Anstieg der weissen Blutkörperchen (Hyperleukozytose)","Bauchspeicheldrüsenentzündung (Pankreatitis)","Sweet-Syndrom, Gefässentzündung (Vaskulitis), Erythema nodosum","Geschwüre im Genitalbereich","Erhöhtes Calcium im Blut (Hyperkalzämie)","Pigmentveränderungen und erhöhte Lichtempfindlichkeit der Haut (Creme)"]},"schwangerschaft":"Kontraindiziert, auch als Creme: Tretinoin kann schwere Fehlbildungen verursachen. Frauen im gebärfähigen Alter müssen während der Kapseltherapie und bis 1 Monat danach zuverlässig verhüten.","stillzeit":"Bei Einnahme der Kapseln kontraindiziert – vorher abstillen. Die Creme in der Stillzeit nur nach ärztlicher Abwägung und nie im Brustbereich anwenden.","hinweise":["Creme abends dünn auf die gereinigte, trockene Haut auftragen; die Akne bessert sich oft erst nach mehreren Wochen, anfangs ist eine Verschlechterung möglich.","Sonne, Solarium und UV-Licht meiden, tagsüber Sonnenschutz verwenden.","Kapseln mit einer Mahlzeit oder kurz danach unzerkaut einnehmen.","Bei Fieber, Atemnot, rascher Gewichtszunahme oder starken Kopfschmerzen während der Kapseltherapie sofort die behandelnde Ärztin oder den Arzt informieren."],"darreichung":["Creme","Gel (Kombination mit Clindamycin)","Weichkapseln"]},"triamcinolon":{"wirkmechanismus":"Hemmt Entzündungen und allergische Reaktionen stark. Triamcinolon ist ein synthetisches Glukokortikoid, etwa fünfmal stärker entzündungshemmend als Cortisol und praktisch ohne salzbindende (mineralokortikoide) Wirkung. Es bindet an den Glukokortikoid-Rezeptor und unterdrückt die Bildung von Entzündungsbotenstoffen sowie die Aktivität von Immunzellen. Als schwer lösliche Kristallsuspension (Triamcinolonacetonid) wird es nach der Injektion über Wochen freigesetzt; im Nasenspray wirkt es vor allem örtlich.","nebenwirkungen":{"haeufig":["Kopfschmerzen, Nasenbluten, Rachenentzündung (Nasenspray)"],"unbekannt":["Cushing-Syndrom, Unterdrückung der Nebennierenfunktion und Zyklusstörungen (auch nach einer einzelnen Depotspritze möglich)","Erhöhter Blutzucker, Wassereinlagerungen, Bluthochdruck, Kaliummangel","Osteoporose, Muskelschwäche, Magen-Darm-Geschwüre bei wiederholter Anwendung","Hautverdünnung, Dellen und helle Flecken an der Einstichstelle; Gesichtsrötung (Flush) nach der Injektion","Vorübergehende Gelenkschmerzen und -schwellung nach der Injektion, Gelenkinfektion, Knochennekrose","Erhöhte Infektanfälligkeit; psychische Veränderungen wie Schlafstörungen, Stimmungsschwankungen, Psychose","Grauer oder grüner Star, verschwommenes Sehen","Anaphylaktische Reaktionen; Reizung und Trockenheit der Nase, selten Perforation der Nasenscheidewand (Nasenspray)"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung; Depotspritzen wirken lange und sollen in der Schwangerschaft möglichst vermieden werden. Nasenspray nur, wenn nötig (begrenzte Daten).","stillzeit":"Glukokortikoide gehen in die Muttermilch über: Depotinjektion nur nach ärztlicher Abwägung. Nasenspray in üblicher Dosis nach Abwägung möglich.","hinweise":["Die Kristallsuspension darf nur in Gelenke, Muskeln oder Gewebe gespritzt werden – nie in die Vene, in den Rückenmarkskanal oder ins Auge.","Nach einer Depotspritze wirkt das Kortison wochenlang: Bei Diabetes Blutzucker engmaschiger messen; vor Operationen die Spritze angeben.","HIV-Medikamente mit Ritonavir oder Cobicistat vor jeder Kortisonspritze unbedingt angeben.","Nasenspray: Die volle Wirkung setzt erst nach einigen Tagen ein; bei Kindern die niedrigste wirksame Dosis verwenden."],"darreichung":["Kristallsuspension zur Injektion (in Gelenk, Muskel oder Hautveränderung)","Nasenspray","Creme (Kombi mit Econazol)"]},"tribenosid":{"wirkmechanismus":"Lindert Schwellung und Entzündung der Hämorrhoiden. Tribenosid vermindert die Durchlässigkeit kleiner Blutgefässe und damit die Ödembildung, wirkt entzündungshemmend, indem es die Wirkung von Botenstoffen wie Histamin und Bradykinin abschwächt, und verbessert die Spannung der Venenwand. Das im Kombipräparat enthaltene Lidocain betäubt zusätzlich die Schleimhaut und lindert rasch Schmerz und Juckreiz.","nebenwirkungen":{"unbekannt":["Lokales Brennen, Juckreiz oder Wärmegefühl","Allergische Hautreaktionen (Rötung, Ausschlag)","Überempfindlichkeitsreaktionen mit Schwellungen (Angioödem)"]},"schwangerschaft":"Im ersten Schwangerschaftsdrittel nicht anwenden; danach nur nach ärztlicher Rücksprache.","stillzeit":"Nur nach Rücksprache mit Ärztin, Arzt oder Apotheke anwenden.","hinweise":["Morgens und abends, vorzugsweise nach dem Stuhlgang, anwenden.","Bei Blut im Stuhl oder fehlender Besserung nach einer Woche ärztlich abklären lassen."],"darreichung":["Rektalcreme","Zäpfchen"]},"trientin":{"wirkmechanismus":"Bindet überschüssiges Kupfer im Körper, damit es über den Urin ausgeschieden werden kann. Trientin ist ein Chelatbildner, der mit Kupfer einen stabilen, wasserlöslichen Komplex bildet, der über die Niere ausgeschieden wird. Zusätzlich vermindert es vermutlich die Aufnahme von Kupfer aus dem Darm. So sinkt die Kupferbelastung von Leber, Gehirn und anderen Organen.","nebenwirkungen":{"haeufig":["Übelkeit"],"gelegentlich":["Hautausschlag"],"unbekannt":["Duodenitis (Zwölffingerdarmentzündung)","Kolitis (Dickdarmentzündung), auch schwer"]},"schwangerschaft":"Die Behandlung des Morbus Wilson wird in der Regel weitergeführt; Anwendung nach sorgfältiger ärztlicher Abwägung mit Kontrolle der Kupferwerte (Kupfermangel kann das Ungeborene schädigen).","stillzeit":"Nicht bekannt, ob Trientin in die Muttermilch übergeht; über Stillen oder Behandlung wird nach ärztlicher Abwägung entschieden.","hinweise":["Nüchtern einnehmen: mindestens 1 Stunde vor oder 2 Stunden nach einer Mahlzeit und mit mindestens 1 Stunde Abstand zu anderen Medikamenten.","Die Behandlung ist lebenslang; regelmässige Kontrollen von Kupfer in Blut und Urin, Blutbild und Leberwerten.","Trientin-Präparate mit verschiedenen Salzformen sind nicht direkt austauschbar (unterschiedliche Dosierungsangaben)."],"darreichung":["Filmtabletten"]},"trifaroten":{"wirkmechanismus":"Normalisiert die Verhornung der Haut und beugt verstopften Poren vor. Trifaroten ist ein Retinoid der neueren Generation, das selektiv den Retinsäure-Rezeptor gamma (RAR-γ) aktiviert, den in der Oberhaut häufigsten Retinsäure-Rezeptor. Dadurch werden Gene für Zellreifung und Entzündung reguliert: Die übermässige Verhornung der Talgdrüsenausgänge geht zurück, Komedonen lösen sich und entzündliche Läsionen nehmen ab. Nur sehr geringe Mengen gelangen ins Blut und werden in der Leber rasch abgebaut.","nebenwirkungen":{"haeufig":["Reizung an der Auftragsstelle (Rötung, Schuppung, Trockenheit, Brennen, Stechen)","Juckreiz an der Auftragsstelle","Sonnenbrand"],"gelegentlich":["Schmerzen an der Auftragsstelle","Hautverfärbung oder Hautabschürfung (Erosion) an der Auftragsstelle","Verschlechterung der Akne","Allergische Dermatitis","Hautausschlag, Schwellung an der Auftragsstelle"],"selten":["Nesselsucht (Urtikaria)","Bläschen an der Auftragsstelle","Lippenentzündung (Cheilitis)","Schwellung der Augenlider","Dunklere Hautstellen (Hyperpigmentierung)","Hautrisse (Fissuren)"]},"schwangerschaft":"Kontraindiziert. Retinoide zum Einnehmen verursachen Fehlbildungen; auch die Creme darf in der Schwangerschaft und bei Kinderwunsch nicht verwendet werden. Bei Eintritt einer Schwangerschaft die Behandlung sofort beenden.","stillzeit":"Ein Risiko für den Säugling ist nicht auszuschliessen – nur nach ärztlicher Abwägung und nie im Brustbereich auftragen.","hinweise":["Einmal täglich abends dünn auf die saubere, trockene Haut auftragen; danach die Hände waschen.","Von Beginn an eine feuchtigkeitsspendende Pflege und tagsüber Sonnenschutz verwenden.","Bei starker Reizung nach ärztlicher Rücksprache seltener anwenden oder pausieren.","Keine Haarentfernung mit Wachs und keine Peelings an den behandelten Stellen."],"darreichung":["Creme"]},"trimipramin":{"wirkmechanismus":"Hellt die Stimmung auf und wirkt ausgeprägt beruhigend und schlaffördernd. Im Unterschied zu anderen Trizyklika hemmt Trimipramin die Wiederaufnahme von Serotonin und Noradrenalin nur schwach; im Vordergrund steht die Blockade von Histamin-H1-, Serotonin-5-HT2-, Alpha-1- und Dopamin-D2-Rezeptoren. Die Blockade von Muskarinrezeptoren (anticholinerge Wirkung) erklärt Nebenwirkungen wie Mundtrockenheit und Verstopfung. Die schlaffördernde Wirkung setzt rasch ein, die antidepressive Wirkung entwickelt sich über 2–4 Wochen.","nebenwirkungen":{"sehrHaeufig":["Mundtrockenheit","Müdigkeit, Benommenheit","Schwindel, Blutdruckabfall beim Aufstehen (orthostatische Hypotonie)","Verstopfung","Gewichtszunahme","Herzklopfen, Herzrasen (Tachykardie)","Zittern (Tremor)","Vermehrtes Schwitzen"],"haeufig":["Sehstörungen (Akkommodationsstörungen)","Störungen beim Wasserlassen","Innere Unruhe, Kopfschmerzen","Durstgefühl","Libido- und Potenzstörungen","Übelkeit"],"gelegentlich":["Harnverhalt","Verwirrtheit und Delir (vor allem bei älteren Menschen)","Hautausschlag, Juckreiz","Krampfanfälle","Wassereinlagerungen (Ödeme)"],"selten":["Herzrhythmus- und Reizleitungsstörungen","Darmlähmung (paralytischer Ileus)","Leberfunktionsstörungen, Gelbsucht","Milchfluss (Galaktorrhö)","Kreislaufkollaps"],"sehrSelten":["Agranulozytose und andere Blutbildveränderungen","Akutes Glaukom"],"unbekannt":["QT-Verlängerung, Torsade de pointes","Hyponatriämie (Natriummangel)","Suizidgedanken und suizidales Verhalten","Absetzsymptome"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit nach ärztlicher Abwägung. Bei Einnahme bis zur Geburt sind beim Neugeborenen Entzugs- und Anpassungsstörungen möglich.","stillzeit":"Trimipramin geht in die Muttermilch über; während der Behandlung soll nicht gestillt werden.","hinweise":["Wegen der dämpfenden Wirkung die Hauptdosis am Abend einnehmen.","Kann die Fahrtüchtigkeit stark beeinträchtigen; Alkohol meiden.","Nicht abrupt absetzen, sondern schrittweise nach ärztlicher Anleitung reduzieren.","Regelmässig EKG, Blutdruck, Blutbild und Leberwerte kontrollieren lassen."],"darreichung":["Tabletten"]},"triptorelin":{"wirkmechanismus":"Schaltet über die Hirnanhangsdrüse die Bildung von Geschlechtshormonen ab. Triptorelin ist ein synthetisches GnRH-Analogon mit stärkerer Wirkung als das natürliche Hormon. Nach einem kurzen Anstieg von LH, FSH und Sexualhormonen führt die Dauerstimulation zur Desensibilisierung der Hypophyse, sodass Testosteron bzw. Östradiol auf Kastrationsniveau sinken. Bei der künstlichen Befruchtung verhindert dies einen vorzeitigen Eisprung.","nebenwirkungen":{"sehrHaeufig":["Hitzewallungen","Vermehrtes Schwitzen","Libidoabnahme, Erektionsstörungen","Schwäche","Kopfschmerzen und Scheidentrockenheit (bei Frauen)"],"haeufig":["Reaktionen an der Injektionsstelle","Gelenk-, Muskel- und Knochenschmerzen","Übelkeit","Stimmungsschwankungen, Depression, Schlafstörungen","Gewichtszunahme","Schwindel","Ovarielles Überstimulationssyndrom (bei künstlicher Befruchtung)","Schmierblutungen (bei Kindern und Frauen zu Beginn)"],"gelegentlich":["Erhöhter Blutdruck, Herzklopfen","Erhöhte Leberwerte","Sehstörungen"],"unbekannt":["Anaphylaxie, Angioödem","QT-Verlängerung","Abnahme der Knochendichte","Hypophysenapoplexie (Einblutung in einen Hypophysentumor)","Krampfanfälle"]},"schwangerschaft":"Kontraindiziert. Vor Beginn Schwangerschaft ausschliessen und während der Behandlung nicht hormonell verhüten.","stillzeit":"Kontraindiziert.","hinweise":["In den ersten Wochen können Beschwerden vorübergehend zunehmen (Flare).","Termine für die Depotspritze genau einhalten.","Bei Langzeitbehandlung Knochendichte und Blutzucker kontrollieren."],"darreichung":["Pulver und Lösungsmittel zur Herstellung einer Depot-Injektionssuspension","Injektionslösung (Fertigspritze)"]},"trospium":{"wirkmechanismus":"Entspannt den überaktiven Blasenmuskel und verringert so Harndrang und unwillkürlichen Urinverlust. Trospium blockiert als Antagonist die Muskarinrezeptoren der glatten Muskulatur, besonders am Blasenmuskel (Detrusor). Als quartäre Ammoniumverbindung ist es dauerhaft geladen und überwindet die Blut-Hirn-Schranke kaum, was zentrale Nebenwirkungen wie Verwirrtheit selten macht. Es wird kaum über Cytochrom-P450-Enzyme abgebaut und überwiegend unverändert über die Nieren (aktive tubuläre Sekretion) ausgeschieden.","nebenwirkungen":{"sehrHaeufig":["Mundtrockenheit"],"haeufig":["Verdauungsbeschwerden (Dyspepsie)","Verstopfung","Bauchschmerzen","Übelkeit"],"gelegentlich":["Herzrasen (Tachykardie)","Durchfall","Blähungen"],"selten":["Sehstörungen (Akkommodationsstörungen)","Erschwertes Wasserlassen, Restharnbildung","Hautausschlag","Tachyarrhythmie","Atemnot","Schwäche","Leichter bis mässiger Anstieg der Leberwerte (Transaminasen)"],"sehrSelten":["Harnverhalt","Kopfschmerzen, Schwindel","Muskel- und Gelenkschmerzen","Angioödem","Anaphylaxie (schwere allergische Reaktion)"],"unbekannt":["Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse (schwere Hautreaktionen)","Halluzinationen, Verwirrtheit, Unruhe"]},"schwangerschaft":"Nur nach strenger ärztlicher Nutzen-Risiko-Abwägung – es liegen keine ausreichenden Erfahrungen am Menschen vor.","stillzeit":"Nicht empfohlen – im Tierversuch ging Trospium in geringen Mengen in die Milch über.","hinweise":["Vor einer Mahlzeit auf nüchternen Magen mit Wasser einnehmen – Nahrung vermindert die Aufnahme deutlich.","Sehstörungen können die Fahrtüchtigkeit beeinträchtigen.","Die Notwendigkeit der Behandlung nach einigen Monaten ärztlich überprüfen lassen."],"darreichung":["Dragées (überzogene Tabletten)"]}});
